begin;
    with j as (select * from jsonb_to_recordset($law7v010$[{"code_id":"GK_RF","article_number":"381.1","version_date":"1994-11-30","article_text":"1. Денежное обязательство, в том числе обязанность возместить убытки или уплатить неустойку в случае нарушения договора, и обязательство, возникшее по основаниям, предусмотренным пунктом 2 статьи 1062 настоящего Кодекса, по соглашению сторон могут быть обеспечены внесением одной из сторон в пользу другой стороны определенной денежной суммы (обеспечительный платеж). Обеспечительным платежом может быть обеспечено обязательство, которое возникнет в будущем.\n\nПри наступлении обстоятельств, предусмотренных договором, сумма обеспечительного платежа засчитывается в счет исполнения соответствующего обязательства.\n\n2. В случае ненаступления в предусмотренный договором срок обстоятельств, указанных в абзаце втором пункта 1 настоящей статьи, или прекращения обеспеченного обязательства обеспечительный платеж подлежит возврату, если иное не предусмотрено соглашением сторон.\n\n3. Договором может быть предусмотрена обязанность соответствующей стороны дополнительно внести или частично возвратить обеспечительный платеж при наступлении определенных обстоятельств.\n\n4. На сумму обеспечительного платежа проценты, установленные статьей 3171 настоящего Кодекса, не начисляются, если иное не предусмотрено договором.","article_title":"Статья 381.1. Обеспечительный платеж","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c28a51b4c3b77d0c082f9d9d07a9f23ef3279f523c5e484d80eed704be7b9f4e"},{"code_id":"GK_RF","article_number":"381.2","version_date":"1994-11-30","article_text":"Правила об обеспечительном платеже (статья 3811) применяются также в случаях, если в счет обеспечения вносятся подлежащие передаче по обеспечиваемому обязательству акции, облигации, иные ценные бумаги или вещи, определенные родовыми признаками. Если в счет обеспечения исполнения обязательств вносятся ценные бумаги, особенности обеспечительного платежа могут быть установлены законами о ценных бумагах. (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)\n\n(Параграф в редакции Федерального закона от 21.12.2013 № 367-ФЗ)\n\n1. Общие положения","article_title":"Статья 381.2. Применение правил об обеспечительном платеже","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ab0742021805442bea6a5c9a2331868445b33b473195445f20360bb1ca5aee4a"},{"code_id":"GK_RF","article_number":"382","version_date":"1994-11-30","article_text":"1. Право (требование), принадлежащее на основании обязательства кредитору, может быть передано им другому лицу по сделке (уступка требования) или может перейти к другому лицу на основании закона.\n\n2. Для перехода к другому лицу прав кредитора не требуется согласие должника, если иное не предусмотрено законом или договором.\n\nАбзац. (Утратил силу - Федеральный закон от 26.07.2017 № 212-ФЗ)\n\nПредусмотренный договором запрет перехода прав кредитора к другому лицу не препятствует продаже таких прав в порядке, установленном законодательством об исполнительном производстве и законодательством о несостоятельности (банкротстве).\n\n3. Если должник не был уведомлен в письменной форме о состоявшемся переходе прав кредитора к другому лицу, новый кредитор несет риск вызванных этим неблагоприятных для него последствий. Обязательство должника прекращается его исполнением первоначальному кредитору, произведенным до получения уведомления о переходе права к другому лицу.\n\n4. Первоначальный кредитор и новый кредитор солидарно обязаны возместить должнику - физическому лицу необходимые расходы, вызванные переходом права, в случае, если уступка, которая повлекла такие расходы, была совершена без согласия должника. Иные правила возмещения расходов могут быть предусмотрены в соответствии с законами о ценных бумагах.","article_title":"Статья 382. Основания и порядок перехода прав кредитора к другому лицу","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"94ee0fbcd5d5a832927df22951efa23e0b5c27a03a269fec3e2f5fccd55c3930"},{"code_id":"GK_RF","article_number":"383","version_date":"1994-11-30","article_text":"Переход к другому лицу прав, неразрывно связанных с личностью кредитора, в частности требований об алиментах и о возмещении вреда, причиненного жизни или здоровью, не допускается.","article_title":"Статья 383. Права, которые не могут переходить к другим лицам","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2275e59d74e1c3ca645a88b28c28e771f5ba22c7719945f20adec99e379e30f8"},{"code_id":"GK_RF","article_number":"384","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено законом или договором, право первоначального кредитора переходит к новому кредитору в том объеме и на тех условиях, которые существовали к моменту перехода права. В частности, к новому кредитору переходят права, обеспечивающие исполнение обязательства, а также другие связанные с требованием права, в том числе право на проценты.\n\n2. Право требования по денежному обязательству может перейти к другому лицу в части, если иное не предусмотрено законом.\n\n3. Если иное не предусмотрено законом или договором, право на получение исполнения иного, чем уплата денежной суммы, может перейти к другому лицу в части при условии, что соответствующее обязательство делимо и частичная уступка не делает для должника исполнение его обязательства значительно более обременительным.","article_title":"Статья 384. Объем прав кредитора, переходящих к другому лицу","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f383ef4f8a497cc33a5f6e7e41e3d3a56fa6ac842c51bd90e7d0003fdf7644d6"},{"code_id":"GK_RF","article_number":"385","version_date":"1994-11-30","article_text":"1. Уведомление должника о переходе права имеет для него силу независимо от того, первоначальным или новым кредитором оно направлено.\n\nДолжник вправе не исполнять обязательство новому кредитору до предоставления ему доказательств перехода права к этому кредитору, за исключением случаев, если уведомление о переходе права получено от первоначального кредитора.\n\n2. Если должник получил уведомление об одном или о нескольких последующих переходах права, должник считается исполнившим обязательство надлежащему кредитору при исполнении обязательства в соответствии с уведомлением о последнем из этих переходов права.\n\n3. Кредитор, уступивший требование другому лицу, обязан передать ему документы, удостоверяющие право (требование), и сообщить сведения, имеющие значение для осуществления этого права (требования).","article_title":"Статья 385. Уведомление должника о переходе права","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"86f06c56ec72b0d8474f31a7d4a3fba902487ad0c4858958ef679b4c5e132fb7"},{"code_id":"GK_RF","article_number":"386","version_date":"1994-11-30","article_text":"Должник вправе выдвигать против требования нового кредитора возражения, которые он имел против первоначального кредитора, если основания для таких возражений возникли к моменту получения уведомления о переходе прав по обязательству к новому кредитору. Должник в разумный срок после получения указанного уведомления обязан сообщить новому кредитору о возникновении известных ему оснований для возражений и предоставить ему возможность ознакомления с ними. В противном случае должник не вправе ссылаться на такие основания. (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 386. Возражения должника против требования нового кредитора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f483b816e812d2305953b859d1cb18800a34ff8a2343812b74c9df51fd846217"},{"code_id":"GK_RF","article_number":"387","version_date":"1994-11-30","article_text":"1. Права кредитора по обязательству переходят к другому лицу на основании закона при наступлении указанных в нем обстоятельств:\n\n1) в результате универсального правопреемства в правах кредитора;\n\n2) по решению суда о переводе прав кредитора на другое лицо, если возможность такого перевода предусмотрена законом;\n\n3) вследствие исполнения обязательства поручителем должника или не являющимся должником по этому обязательству залогодателем;\n\n4) при суброгации страховщику прав кредитора к должнику, ответственному за наступление страхового случая;\n\n5) в других случаях, предусмотренных законом.\n\n2. К отношениям, связанным с переходом прав на основании закона, применяются правила настоящего Кодекса об уступке требования (статьи 388 - 390), если иное не установлено настоящим Кодексом, другими законами или не вытекает из существа отношений.\n\n3. Уступка требования (цессия)","article_title":"Статья 387. Переход прав кредитора к другому лицу на основании закона","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c238a825b5cad7bf3b37181c702fb637e84613674a96e3210ebcbcbe6a593b3f"},{"code_id":"GK_RF","article_number":"388","version_date":"1994-11-30","article_text":"1. Уступка требования кредитором (цедентом) другому лицу (цессионарию) допускается, если она не противоречит закону.\n\n2. Не допускается без согласия должника уступка требования по обязательству, в котором личность кредитора имеет существенное значение для должника.\n\nСоглашением между должником и цедентом может быть запрещена или ограничена уступка права на получение неденежного исполнения.\n\nЕсли договором был предусмотрен запрет уступки права на получение неденежного исполнения, соглашение об уступке может быть признано недействительным по иску должника только в случае, когда доказано, что другая сторона соглашения знала или должна была знать об указанном запрете. (Дополнение абзацем - Федеральный закон от 26.07.2017 № 212-ФЗ)","article_title":"Статья 388. Условия уступки требования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"334c3bf9d0587da9c9ef1bf9b647dedaf0b2839b0512dc9f95767b5cd67313bd"},{"code_id":"GK_RF","article_number":"389","version_date":"1994-11-30","article_text":"1. Уступка требования, основанного на сделке, совершенной в простой письменной или нотариальной форме, должна быть совершена в соответствующей письменной форме.\n\n2. Соглашение об уступке требования по сделке, требующей государственной регистрации, должно быть зарегистрировано в порядке, установленном для регистрации этой сделки, если иное не установлено законом.","article_title":"Статья 389. Форма уступки требования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cf023c0c5d2554e7df818e93edcee9a59cbe7a6e0f0d7b1575a1bb04473f2440"},{"code_id":"GK_RF","article_number":"389.1","version_date":"1994-11-30","article_text":"1. Взаимные права и обязанности цедента и цессионария определяются настоящим Кодексом и договором между ними, на основании которого производится уступка.\n\n2. Требование переходит к цессионарию в момент заключения договора, на основании которого производится уступка, если законом или договором не предусмотрено иное.\n\n3. Если иное не предусмотрено договором, цедент обязан передать цессионарию все полученное от должника в счет уступленного требования.","article_title":"Статья 389.1. Права и обязанности цедента и цессионария","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"060b951330073db598125c5db07f1f79f9e4b2bb1a07cafab57494e2ed3c65bd"},{"code_id":"GK_RF","article_number":"39","version_date":"1994-11-30","article_text":"1. Орган опеки и попечительства освобождает опекуна или попечителя от исполнения им своих обязанностей в случаях возвращения несовершеннолетнего его родителям или его усыновления.\n\nПри помещении подопечного под надзор в образовательную организацию, медицинскую организацию, организацию, оказывающую социальные услуги, или иную организацию, в том числе в организацию для детей-сирот и детей, оставшихся без попечения родителей, орган опеки и попечительства освобождает ранее назначенного опекуна или попечителя от исполнения ими своих обязанностей, если это не противоречит интересам подопечного. (В редакции Федерального закона от 24.04.2008 № 49-ФЗ)\n\n2. Опекун, попечитель могут быть освобождены от исполнения своих обязанностей по их просьбе.\n\nОпекун или попечитель может быть освобожден от исполнения своих обязанностей по инициативе органа опеки и попечительства в случае возникновения противоречий между интересами подопечного и интересами опекуна или попечителя, в том числе временно.\n\n(Пункт в редакции Федерального закона от 24.04.2008 № 49-ФЗ)\n\n3. В случаях ненадлежащего выполнения опекуном или попечителем лежащих на нем обязанностей, в том числе при использовании им опеки или попечительства в корыстных целях или при оставлении подопечного без надзора и необходимой помощи, орган опеки и попечительства может отстранить опекуна или попечителя от исполнения этих обязанностей и принять необходимые меры для привлечения виновного гражданина к установленной законом ответственности.","article_title":"Статья 39. Освобождение и отстранение опекунов и попечителей от исполнения ими своих обязанностей","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"235c2551ffdc3ed94f92b3a4a3842a1decacadea40c0ac452e077b1b2a4f8d35"},{"code_id":"GK_RF","article_number":"390","version_date":"1994-11-30","article_text":"1. Цедент отвечает перед цессионарием за недействительность переданного ему требования, но не отвечает за неисполнение этого требования должником, за исключением случая, если цедент принял на себя поручительство за должника перед цессионарием.\n\nЕсли иное не предусмотрено законом, договор, на основании которого производится уступка, может предусматривать, что цедент не несет ответственности перед цессионарием за недействительность переданного ему требования по договору, исполнение которого связано с осуществлением его сторонами предпринимательской деятельности, при условии, что такая недействительность вызвана обстоятельствами, о которых цедент не знал или не мог знать или о которых он предупредил цессионария, в том числе обстоятельствами, относящимися к дополнительным требованиям, включая требования по правам, обеспечивающим исполнение обязательства, и правам на проценты. (Дополнение абзацем - Федеральный закон от 26.07.2017 № 212-ФЗ)\n\n2. При уступке цедентом должны быть соблюдены следующие условия:\n\nуступаемое требование существует в момент уступки, если только это требование не является будущим требованием;\n\nцедент правомочен совершать уступку;\n\nуступаемое требование ранее не было уступлено цедентом другому лицу;\n\nцедент не совершал и не будет совершать никакие действия, которые могут служить основанием для возражений должника против уступленного требования.\n\nЗаконом или договором могут быть предусмотрены и иные требования, предъявляемые к уступке.\n\n3. При нарушении цедентом правил, предусмотренных пунктами 1 и 2 настоящей статьи, цессионарий вправе потребовать от цедента возврата всего переданного по соглашению об уступке, а также возмещения причиненных убытков.\n\n4. В отношениях между несколькими лицами, которым одно и то же требование передавалось от одного цедента, требование признается перешедшим к лицу, в пользу которого передача была совершена ранее.\n\nВ случае исполнения должником другому цессионарию риск последствий такого исполнения несет цедент или цессионарий, которые знали или должны были знать об уступке требования, состоявшейся ранее.","article_title":"Статья 390. Ответственность цедента","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c8de0a83efdf6e96799b0fbc9822b030d2f015bfd33da0ddc2230c4764617fe1"},{"code_id":"GK_RF","article_number":"391","version_date":"1994-11-30","article_text":"1. Перевод долга с должника на другое лицо может быть произведен по соглашению между первоначальным должником и новым должником.\n\nВ обязательствах, связанных с осуществлением их сторонами предпринимательской деятельности, перевод долга может быть произведен по соглашению между кредит\n\nором и новым должником, согласно которому новый должник принимает на себя обязательство первоначального должника.\n\n2. Перевод должником своего долга на другое лицо допускается с согласия кредитора и при отсутствии такого согласия является ничтожным.\n\nЕсли кредитор дает предварительное согласие на перевод долга, этот перевод считается состоявшимся в момент получения кредитором уведомления о переводе долга.\n\n3. При переводе долга по обязательству, связанному с осуществлением его сторонами предпринимательской деятельности, в случае, предусмотренном абзацем вторым пункта 1 настоящей статьи, первоначальный должник и новый должник несут солидарную ответственность перед кредитором, если соглашением о переводе долга не предусмотрена субсидиарная ответственность первоначального должника либо первоначальный должник не освобожден от исполнения обязательства. Первоначальный должник вправе отказаться от освобождения от исполнения обязательства.\n\nК новому должнику, исполнившему обязательство, связанное с осуществлением его сторонами предпринимательской деятельности, переходят права кредитора по этому обязательству, если иное не предусмотрено соглашением между первоначальным должником и новым должником или не вытекает из существа их отношений.\n\n4. К форме перевода долга соответственно применяются правила, содержащиеся в статье 389 настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 21.12.2013 № 367-ФЗ)","article_title":"Статья 391. Условия и форма перевода долга","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"803c410c94e0c782273d52b6cb097eaa614fb1371660f047038826a2693de66b"},{"code_id":"GK_RF","article_number":"392","version_date":"1994-11-30","article_text":"Новый должник вправе выдвигать против требования кредитора возражения, основанные на отношениях между кредитором и первоначальным должником, но не вправе осуществлять в отношении кредитора право на зачет встречного требования, принадлежащего первоначальному должнику. (В редакции Федерального закона от 21.12.2013 № 367-ФЗ)","article_title":"Статья 392. Возражения нового должника против требования кредитора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6f4a0e20124df1cc8e799447136ab59796409729f8a6e00b36deaa2b89d7176b"},{"code_id":"GK_RF","article_number":"392.1","version_date":"1994-11-30","article_text":"1. Кредитор может осуществлять в отношении нового должника все права по обязательству, если иное не предусмотрено законом, договором или не вытекает из существа обязательства.\n\n2. Если при переводе долга первоначальный должник освобожден от обязательства, обеспечение исполнения обязательства, предоставленное третьим лицом, прекращается, за исключением случая, когда такое лицо согласилось отвечать за нового должника.\n\n3. Освобождение первоначального должника от обязательства распространяется на всякое предоставленное им обеспечение, если только имущество, являющееся предметом обеспечения, не передано им новому должнику.\n\n(Дополнение статьей - Федеральный закон от 21.12.2013 № 367-ФЗ)","article_title":"Статья 392.1. Права кредитора в отношении нового должника","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5d21ae8df835aae5c94bc00739c79509874abf765cbfe1f58a56039faec04db6"},{"code_id":"GK_RF","article_number":"392.2","version_date":"1994-11-30","article_text":"1. Долг может перейти с должника на другое лицо по основаниям, предусмотренным законом.\n\n2. Для перехода долга в силу закона не требуется согласие кредитора, если иное не установлено законом или не вытекает из существа обязательства.\n\n(Дополнение статьей - Федеральный закон от 21.12.2013 № 367-ФЗ)","article_title":"Статья 392.2. Переход долга в силу закона","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4c86fc0441295c8ddab4f87cbd9f2b8836eced86d65cd541c1b6b3a31fd607ed"},{"code_id":"GK_RF","article_number":"392.3","version_date":"1994-11-30","article_text":"В случае одновременной передачи стороной всех прав и обязанностей по договору другому лицу (передача договора) к сделке по передаче соответственно применяются правила об уступке требования и о переводе долга.\n\n(Дополнение статьей - Федеральный закон от 21.12.2013 № 367-ФЗ)","article_title":"Статья 392.3. Передача договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5b532dcb3c5d33a0108c495f21ac8dfa755b826b16b56484d35bee60391200a3"},{"code_id":"GK_RF","article_number":"393","version_date":"1994-11-30","article_text":"1. Должник обязан возместить кредитору убытки, причиненные неисполнением или ненадлежащим исполнением обязательства.\n\nЕсли иное не установлено законом, использование кредитором иных способов защиты нарушенных прав, предусмотренных законом или договором, не лишает его права требовать от должника возмещения убытков, причиненных неисполнением или ненадлежащим исполнением обязательства. (Дополнение абзацем - Федеральный закон от 08.03.2015 № 42-ФЗ)\n\n2. Убытки определяются в соответствии с правилами, предусмотренными статьей 15 настоящего Кодекса.\n\nВозмещение убытков в полном размере означает, что в результате их возмещения кредитор должен быть поставлен в положение, в котором он находился бы, если бы обязательство было исполнено надлежащим образом. (Дополнение абзацем - Федеральный закон от 08.03.2015 № 42-ФЗ)\n\n3. Если иное не предусмотрено законом, иными правовыми актами или договором, при определении убытков принимаются во внимание цены, существовавшие в том месте, где обязательство должно было быть исполнено, в день добровольного удовлетворения должником требования кредитора, а если требование добровольно удовлетворено не было, - в день предъявления иска. Исходя из обстоятельств, суд может удовлетворить требование о возмещении убытков, принимая во внимание цены, существующие в день вынесения решения.\n\n4. При определении упущенной выгоды учитываются предпринятые кредитором для ее получения меры и сделанные с этой целью приготовления.","article_title":"Статья 393. Обязанность должника возместить убытки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fe8eb20b905999cf6007616845ae9e40a43b13dc6d69bd2f6fb3df7fd6c2939c"},{"code_id":"GK_RF","article_number":"393.1","version_date":"1994-11-30","article_text":"1. В случае, если неисполнение или ненадлежащее исполнение должником договора повлекло его досрочное прекращение и кредитор заключил взамен его аналогичный договор, кредитор вправе потребовать от должника возмещения убытков в виде разницы между ценой, установленной в прекращенном договоре, и ценой на сопоставимые товары, работы или услуги по условиям договора, заключенного взамен прекращенного договора.\n\n2. Если кредитор не заключил аналогичный договор взамен прекращенного договора (пункт 1 настоящей статьи), но в отношении предусмотренного прекращенным договором исполнения имеется текущая цена на сопоставимые товары, работы или услуги, кредитор вправе потребовать от должника возмещения убытков в виде разницы между ценой, установленной в прекращенном договоре, и текущей ценой.\n\nТекущей ценой признается цена, взимаемая в момент прекращения договора за сопоставимые товары, работы или услуги в месте, где должен был быть исполнен договор, а при отсутствии текущей цены в указанном месте - цена, которая применялась в другом месте и может служить разумной заменой с учетом транспортных и иных дополнительных расходов.\n\n3. Удовлетворение требований, предусмотренных пунктами 1 и 2 настоящей статьи, не освобождает сторону, не исполнившую обязательства или ненадлежаще его исполнившую, от возмещения иных убытков, причиненных другой стороне.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 393.1. Возмещение убытков при прекращении договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"03010b84f3909dec8d2fda8ee7bad5e8995620efc0d6bbf02a0855d177c31392"},{"code_id":"GK_RF","article_number":"394","version_date":"1994-11-30","article_text":"1. Если за неисполнение или ненадлежащее исполнение обязательства установлена неустойка, то убытки возмещаются в части, не покрытой неустойкой.\n\nЗаконом или договором могут быть предусмотрены случаи: когда допускается взыскание только неустойки, но не убытков; когда убытки могут быть взысканы в полной сумме сверх неустойки; когда по выбору кредитора могут быть взысканы либо неустойка, либо убытки.\n\n2. В случаях, когда за неисполнение или ненадлежащее исполнение обязательства установлена ограниченная ответственность (статья 400), убытки, подлежащие возмещению в части, не покрытой неустойкой, либо сверх ее, либо вместо нее, могут быть взысканы до пределов, установленных таким ограничением.","article_title":"Статья 394. Убытки и неустойка","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f4afabfb4830f0ed7e648eab7250cbb27fc226255b2e270c1c51996ddd1b8c8d"},{"code_id":"GK_RF","article_number":"396","version_date":"1994-11-30","article_text":"1. Уплата неустойки и возмещение убытков в случае ненадлежащего исполнения обязательства не освобождают должника от исполнения обязательства в натуре, если иное не предусмотрено законом или договором.\n\n2. Возмещение убытков в случае неисполнения обязательства и уплата неустойки за его неисполнение освобождают должника от исполнения обязательства в натуре, если иное не предусмотрено законом или договором.\n\n3. Отказ кредитора от принятия исполнения, которое вследствие просрочки утратило для него интерес (пункт 2 статьи 405), а также уплата неустойки, установленной в качестве отступного (статья 409), освобождают должника от исполнения обязательства в натуре.","article_title":"Статья 396. Ответственность и исполнение обязательства в натуре","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dbe2d6a7598fbff0095936d21f74d6fac38307f0eefd569a02769368c7ac43a0"},{"code_id":"GK_RF","article_number":"397","version_date":"1994-11-30","article_text":"В случае неисполнения должником обязательства изготовить и передать вещь в собственность, в хозяйственное ведение или в оперативное управление, либо передать вещь в пользование кредитору, либо выполнить для него определенную работу или оказать ему услугу кредитор вправе в разумный срок поручить выполнение обязательства третьим лицам за разумную цену либо выполнить его своими силами, если иное не вытекает из закона, иных правовых актов, договора или существа обязательства, и потребовать от должника возмещения понесенных необходимых расходов и других убытков.","article_title":"Статья 397. Исполнение обязательства за счет должника","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"50c29b8c24badbd81f16d958cfc3c4ef7eb41bc9d4830ca4f002188444802148"},{"code_id":"GK_RF","article_number":"398","version_date":"1994-11-30","article_text":"В случае неисполнения обязательства передать индивидуально-определенную вещь в собственность, в хозяйственное ведение, в оперативное управление или в возмездное пользование кредитору последний вправе требовать отобрания этой вещи у должника и передачи ее кредитору на предусмотренных обязательством условиях. Это право отпадает, если вещь уже передана третьему лицу, имеющему право собственности, хозяйственного ведения или оперативного управления. Если вещь еще не передана, преимущество имеет тот из кредиторов, в пользу которого обязательство возникло раньше, а если это невозможно установить, - тот, кто раньше предъявил иск.\n\nВместо требования передать ему вещь, являющуюся предметом обязательства, кредитор вправе потребовать возмещения убытков.","article_title":"Статья 398. Последствия неисполнения обязательства передать индивидуально-определенную вещь","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b972be128d019f8b01bc82a3278b7ab714c20b83e7542540d7b4d2ce667229e9"},{"code_id":"GK_RF","article_number":"399","version_date":"1994-11-30","article_text":"1. До предъявления требований к лицу, которое в соответствии с законом, иными правовыми актами или условиями обязательства несет ответственность дополнительно к ответственности другого лица, являющегося основным должником (субсидиарную ответственность), кредитор должен предъявить требование к основному должнику.\n\nЕсли основной должник отказался удовлетворить требование кредитора или кредитор не получил от него в разумный срок ответ на предъявленное требование, это требование может быть предъявлено лицу, несущему субсидиарную ответственность.\n\n2. Кредитор не вправе требовать удовлетворения своего требования к основному должнику от лица, несущего субсидиарную ответственность, если это требование может быть удовлетворено путем зачета встречного требования к основному должнику либо бесспорного взыскания средств с основного должника.\n\n3. Лицо, несущее субсидиарную ответственность, должно до удовлетворения требования, предъявленного ему кредитором, предупредить об этом основного должника, а если к такому лицу предъявлен иск, - привлечь основного должника к участию в деле. В противном случае основной должник имеет право выдвинуть против регрессного требования лица, отвечающего субсидиарно, возражения, которые он имел против кредитора.","article_title":"Статья 399. Субсидиарная ответственность","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7dca2876b40533e7385ad9b683ba258523f89613c609a9abbdfd24ff43a5526c"},{"code_id":"GK_RF","article_number":"4","version_date":"1994-11-30","article_text":"1. Акты гражданского законодательства не имеют обратной силы и применяются к отношениям, возникшим после введения их в действие.\n\nДействие закона распространяется на отношения, возникшие до введения его в действие, только в случаях, когда это прямо предусмотрено законом.\n\n2. По отношениям, возникшим до введения в действие акта гражданского законодательства, он применяется к правам и обязанностям, возникшим после введения его в действие. Отношения сторон по договору, заключенному до введения в действие акта гражданского законодательства, регулируются в соответствии со статьей 422 настоящего Кодекса.","article_title":"Статья 4. Действие гражданского законодательства во времени","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"00553062b918912f8c94afb40dbf167c43f91f830e25068a0e6a35e6f4f8ed56"},{"code_id":"GK_RF","article_number":"40","version_date":"1994-11-30","article_text":"1. Опека и попечительство над совершеннолетними гражданами прекращаются в случаях вынесения судом решения о признании подопечного дееспособным или отмены ограничений его дееспособности по заявлению опекуна, попечителя или органа опеки и попечительства.\n\n2. По достижении малолетним подопечным четырнадцати лет опека над ним прекращается, а гражданин, осуществлявший обязанности опекуна, становится попечителем несовершеннолетнего без дополнительного решения об этом.\n\n3. Попечительство над несовершеннолетним прекращается без особого решения по достижении несовершеннолетним подопечным восемнадцати лет, а также при вступлении его в брак и в других случаях приобретения им полной дееспособности до достижения совершеннолетия (пункт 2 статьи 21 и статья 27).","article_title":"Статья 40. Прекращение опеки и попечительства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f6a74edf89c33d51f4b2fbd94cc5db3a4b1a7b623a36a3833b75ef4bbaf89c23"},{"code_id":"GK_RF","article_number":"400","version_date":"1994-11-30","article_text":"1. По отдельным видам обязательств и по обязательствам, связанным с определенным родом деятельности, законом может быть ограничено право на полное возмещение убытков (ограниченная ответственность).\n\n2. Соглашение об ограничении размера ответственности должника по договору присоединения или иному договору, в котором кредитором является гражданин, выступающий в качестве потребителя, ничтожно, если размер ответственности для данного вида обязательств или за данное нарушение определен законом и если соглашение заключено до наступления обстоятельств, влекущих ответственность за неисполнение или ненадлежащее исполнение обязательства.","article_title":"Статья 400. Ограничение размера ответственности по обязательствам","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2f0110d1ef6b8bd97b90642e93e20b431d3ce021ab436b1b8de46e0cf913de6f"},{"code_id":"GK_RF","article_number":"401","version_date":"1994-11-30","article_text":"1. Лицо, не исполнившее обязательства либо исполнившее его ненадлежащим образом, несет ответственность при наличии вины (умысла или неосторожности), кроме случаев, когда законом или договором предусмотрены иные основания ответственности.\n\nЛицо признается невиновным, если при той степени заботливости и осмотрительности, какая от него требовалась по характеру обязательства и условиям оборота, оно приняло все меры для надлежащего исполнения обязательства.\n\n2. Отсутствие вины доказывается лицом, нарушившим обязательство.\n\n3. Если иное не предусмотрено законом или договором, лицо, не исполнившее или ненадлежащим образом исполнившее обязательство при осуществлении предпринимательской деятельности, несет ответственность, если не докажет, что надлежащее исполнение оказалось невозможным вследствие непреодолимой силы, то есть чрезвычайных и непредотвратимых при данных условиях обстоятельств. К таким обстоятельствам не относятся, в частности, нарушение обязанностей со стороны контрагентов должника, отсутствие на рынке нужных для исполнения товаров, отсутствие у должника необходимых денежных средств.\n\n4. Заключенное заранее соглашение об устранении или ограничении ответственности за умышленное нарушение обязательства ничтожно.","article_title":"Статья 401. Основания ответственности за нарушение обязательства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1a14a93ae5f4ed7264870dea1d14160bb74e25e4076262677cdcc2429551b745"},{"code_id":"GK_RF","article_number":"402","version_date":"1994-11-30","article_text":"Действия работников должника по исполнению его обязательства считаются действиями должника. Должник отвечает за эти действия, если они повлекли неисполнение или ненадлежащее исполнение обязательства.","article_title":"Статья 402. Ответственность должника за своих работников","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2c96d538d7af459dcf76cba90b5a3abee7ad7120395c9287ba8ad01bf469a62f"},{"code_id":"GK_RF","article_number":"403","version_date":"1994-11-30","article_text":"Должник отвечает за неисполнение или ненадлежащее исполнение обязательства третьими лицами, на которых было возложено исполнение, если законом не установлено, что ответственность несет являющееся непосредственным исполнителем третье лицо.","article_title":"Статья 403. Ответственность должника за действия третьих лиц","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c73868f13f2054066b9d05c48c6e5ee1ca8a86561d55b02acedb4bd10ad31f17"},{"code_id":"GK_RF","article_number":"404","version_date":"1994-11-30","article_text":"1. Если неисполнение или ненадлежащее исполнение обязательства произошло по вине обеих сторон, суд соответственно уменьшает размер ответственности должника. Суд также вправе уменьшить размер ответственности должника, если кредитор умышленно или по неосторожности содействовал увеличению размера убытков, причиненных неисполнением или ненадлежащим исполнением, либо не принял разумных мер к их уменьшению.\n\n2. Правила пункта 1 настоящей статьи соответственно применяются и в случаях, когда должник в силу закона или договора несет ответственность за неисполнение или ненадлежащее исполнение обязательства независимо от своей вины.","article_title":"Статья 404. Вина кредитора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a10ef9ef6a854151004b76bdecae0d74d511f915c9be15eda4cdac46d7117276"},{"code_id":"GK_RF","article_number":"405","version_date":"1994-11-30","article_text":"1. Должник, просрочивший исполнение, отвечает перед кредитором за убытки, причиненные просрочкой, и за последствия случайно наступившей во время просрочки невозможности исполнения.\n\n2. Если вследствие просрочки должника исполнение утратило интерес для кредитора, он может отказаться от принятия исполнения и требовать возмещения убытков.\n\n3. Должник не считается просрочившим, пока обязательство не может быть исполнено вследствие просрочки кредитора.","article_title":"Статья 405. Просрочка должника","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bfb2cb0a5aacfb97f9e41801cde9fecf42c69d5a651ae15c8d9c144ff26d995e"},{"code_id":"GK_RF","article_number":"406","version_date":"1994-11-30","article_text":"Кредитор считается просрочившим также в случаях, указанных в пункте 2 статьи 408 настоящего Кодекса.\n\nКредитор не считается просрочившим в случае, если должник был не в состоянии исполнить обязательство, вне зависимости от того, что кредитором не были совершены действия, предусмотренные абзацем первым настоящего пункта. (Дополнение абзацем - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 406. Просрочка кредитора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"195060ff47108544746361d90bc17709bc1e66d154f13f49e166c77a91c8da3a"},{"code_id":"GK_RF","article_number":"406.1","version_date":"1994-11-30","article_text":"1. Стороны обязательства, действуя при осуществлении ими предпринимательской деятельности, могут своим соглашением предусмотреть обязанность одной стороны возместить имущественные потери другой стороны, возникшие в случае наступления определенных в таком соглашении обстоятельств и не связанные с нарушением обязательства его стороной (потери, вызванные невозможностью исполнения обязательства, предъявлением требований третьими лицами или органами государственной власти к стороне ил\n\nи к третьему лицу, указанному в соглашении, и т.п.). Соглашением сторон должен быть определен размер возмещения таких потерь или порядок его определения.\n\n2. Суд не может уменьшить размер возмещения потерь, предусмотренных настоящей статьей, за исключением случаев, если доказано, что сторона умышленно содействовала увеличению размера потерь.\n\n3. Потери, предусмотренные настоящей статьей, возмещаются независимо от признания договора незаключенным или недействительным, если иное не предусмотрено соглашением сторон.\n\n4. В случае, если потери возникли в связи с неправомерными действиями третьего лица, к стороне, возместившей такие потери, переходит требование кредитора к этому третьему лицу о возмещении убытков.\n\n5. Правила настоящей статьи применяются также в случаях, если условие о возмещении потерь предусмотрено в корпоративном договоре либо в договоре об отчуждении акций или долей в уставном капитале хозяйственного общества, стороной которого является физическое лицо.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 406.1. Возмещение потерь, возникших в случае наступления определенных в договоре обстоятельств","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1249ff965fe576769b0faa82af6454e22603c2309ba6521c5c2acb330f3a2210"},{"code_id":"GK_RF","article_number":"407","version_date":"1994-11-30","article_text":"1. Обязательство прекращается полностью или частично по основаниям, предусмотренным настоящим Кодексом, другими законами, иными правовыми актами или договором.\n\n2. Прекращение обязательства по требованию одной из сторон допускается только в случаях, предусмотренных законом или договором.","article_title":"Статья 407. Основания прекращения обязательств","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3f78ea45fb255e0df7080b471d69b701b89dbf6a8cdf2480a94dca6df51de2f9"},{"code_id":"GK_RF","article_number":"408","version_date":"1994-11-30","article_text":"1. Надлежащее исполнение прекращает обязательство.\n\n2. Кредитор, принимая исполнение, обязан по требованию должника выдать ему расписку в получении исполнения полностью или в соответствующей части.\n\nЕсли должник выдал кредитору в удостоверение обязательства долговой документ, то кредитор, принимая исполнение, должен вернуть этот документ, а при невозможности возвращения указать на это в выдаваемой им расписке. Расписка может быть заменена надписью на возвращаемом долговом документе. Нахождение долгового документа у должника удостоверяет, пока не доказано иное, прекращение обязательства.\n\nПри отказе кредитора выдать расписку, вернуть долговой документ или отметить в расписке невозможность его возвращения должник вправе задержать исполнение. В этих случаях кредитор считается просрочившим.","article_title":"Статья 408. Прекращение обязательства исполнением","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f13b69b6d6f125d9ec981ace4163541a426aa5281ad6ea2bcca346559e440e83"},{"code_id":"GK_RF","article_number":"409","version_date":"1994-11-30","article_text":"По соглашению сторон обязательство может быть прекращено предоставлением отступного - уплатой денежных средств или передачей иного имущества.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 409. Отступное","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"64a45c9b109f75989de8f7464cce14d3285cafd6eac927062c97acd97578fde4"},{"code_id":"GK_RF","article_number":"41","version_date":"1994-11-30","article_text":"1. Над совершеннолетним дееспособным гражданином, который по состоянию здоровья не способен самостоятельно осуществлять и защищать свои права и исполнять свои обязанност\n\nи, может быть установлен патронаж.\n\n2. В течение месяца со дня выявления совершеннолетнего дееспособного гражданина, который по состоянию здоровья не может самостоятельно осуществлять и защищать свои права и исполнять свои обязанности, ему назначается органом опеки и попечительства помощник. Помощник может быть назначен с его согласия в письменной форме, а также с согласия в письменной форме гражданина, над которым устанавливается патронаж. Работник организации, осуществляющей социальное обслуживание совершеннолетнего дееспособного гражданина, нуждающегося в установлении над ним патронажа, не может быть назначен помощником такого гражданина.\n\n3. Помощник совершеннолетнего дееспособного гражданина совершает действия в интересах гражданина, находящегося под патронажем, на основании заключаемых с этим лицом договора поручения, договора доверительного управления имуществом или иного договора.\n\n4. Орган опеки и попечительства обязан осуществлять контроль за исполнением помощником совершеннолетнего дееспособного гражданина своих обязанностей и извещать находящегося под патронажем гражданина о нарушениях, допущенных его помощником и являющихся основанием для расторжения заключенных между ними договора поручения, договора доверительного управления имуществом или иного договора.\n\n5. Патронаж над совершеннолетним дееспособным гражданином, установленный в соответствии с пунктом 1 настоящей статьи, прекращается в связи с прекращением договора поручения, договора доверительного управления имуществом или иного договора по основаниям, предусмотренным законом или договором.\n\n(Статья в редакции Федерального закона от 24.04.2008 № 49-ФЗ)","article_title":"Статья 41. Патронаж над совершеннолетними дееспособными гражданами","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"71e37841600fd07fc76358c4f2e34ed79d43df43fc81729df352a6492bae627f"},{"code_id":"GK_RF","article_number":"410","version_date":"1994-11-30","article_text":"Обязательство прекращается полностью или частично зачетом встречного однородного требования, срок которого наступил либо срок которого не указан или определен моментом востребования. В случаях, предусмотренных законом, допускается зачет встречного однородного требования, срок которого не наступил. Для зачета достаточно заявления одной стороны. (В редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 410. Прекращение обязательства зачетом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b849abaa9011bb4b0b34da05d28ff59c1d20f876fd40e6fc9dfdfa1558fb0730"},{"code_id":"GK_RF","article_number":"411","version_date":"1994-11-30","article_text":"Не допускается зачет требований:\n\nо возмещении вреда, причиненного жизни или здоровью;\n\nо пожизненном содержании;\n\nо взыскании алиментов;\n\nпо которым истек срок исковой давности;\n\nв иных случаях, предусмотренных законом или договором.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 411. Случаи недопустимости зачета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"27c5798a044923da7997182422562f48df0a171d5286b4cc729c3d5802e0b4ae"},{"code_id":"GK_RF","article_number":"412","version_date":"1994-11-30","article_text":"В случае уступки требования должник вправе зачесть против требования нового кредитора свое встречное требование к первоначальному кредитору.\n\nЗачет производится, если требование возникло по основанию, существовавшему к моменту получения должником уведомления об уступке требования, и срок требования наступил до его получения либо этот срок не указан или определен моментом востребования.","article_title":"Статья 412. Зачет при уступке требования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c4f32c89a932ee7f21f2fad467a02dcac0cb11e7faf29c82d36cd2893d652e26"},{"code_id":"GK_RF","article_number":"413","version_date":"1994-11-30","article_text":"Обязательство прекращается совпадением должника и кредитора в одном лице, если иное не установлено законом или не вытекает из существа обязательства. (В редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 413. Прекращение обязательства совпадением должника и кредитора в одном лице","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b10af3e9215cb754ad2662574b441e7eb476e11b4dcf1319b87b22c6f972d45c"},{"code_id":"GK_RF","article_number":"414","version_date":"1994-11-30","article_text":"1. Обязательство прекращается соглашением сторон о замене первоначального обязательства, существовавшего между ними, другим обязательством между теми же лицами (новация), если иное не установлено законом или не вытекает из существа отношений.\n\n2. Новация прекращает дополнительные обязательства, связанные с первоначальным обязательством, если иное не предусмотрено соглашением сторон.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 414. Прекращение обязательства новацией","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2d5d22aeddc7c3eb989fa8a1462ed3b2e1e8f8ffc3da59945783aa379bb22d30"},{"code_id":"GK_RF","article_number":"417","version_date":"1994-11-30","article_text":"1. Если в результате издания акта органа государственной власти или органа местного самоуправления исполнение обязательства становится невозможным полностью или частично, обязательство прекращается полностью или в соответствующей части. Стороны, понесшие в результате этого убытки, вправе требовать их возмещения в соответствии со статьями 13 и 16 настоящего Кодекса.\n\n2. Обязательство не считается прекращенным, если издание акта органа государственной власти или органа местного самоуправления, повлекшее невозможность исполнения обязательства, вызвано неправомерными действиями (бездействием) самого должника.\n\n3. В случае признания недействительным либо отмены в установленном порядке акта органа государственной власти или органа местного самоуправления (пункт 1 настоящей статьи) обязательство не считается прекращенным, если иное не вытекает из соглашения сторон или существа обязательства либо если кредитор в разумный срок не отказался от исполнения обязательства.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 417. Прекращение обязательства на основании акта органа государственной власти или органа местного самоуправления","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3e4721833d9d2196d02970b53c9d4547979cdb16e7ab12568cb93de7d43e56e3"},{"code_id":"GK_RF","article_number":"418","version_date":"1994-11-30","article_text":"1. Обязательство прекращается смертью должника, если исполнение не может быть произведено без личного участия должника либо обязательство иным образом неразрывно связано с личностью должника.\n\n2. Обязательство прекращается смертью кредитора, если исполнение предназначено лично для кредитора либо обязательство иным образом неразрывно связано с личностью кредитора.","article_title":"Статья 418. Прекращение обязательства смертью гражданина","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2f7d29e5af0ba9aef551a50d62ac2f91e33a3520011cd47f2e8a25353e30b213"},{"code_id":"GK_RF","article_number":"419","version_date":"1994-11-30","article_text":"Обязательство прекращается ликвидацией юридического лица (должника или кредитора), кроме случаев, когда законом или иными правовыми актами исполнение обязательства ликвидированного юридического лица возлагается на другое лицо (по требованиям о возмещении вреда, причиненного жизни или здоровью, и др.).","article_title":"Статья 419. Прекращение обязательства ликвидацией юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"37f3188a4d00ff9c36c3cf7ecdf708e7c27b95f2ea526fa32bd2a2c394ea4594"},{"code_id":"GK_RF","article_number":"42","version_date":"1994-11-30","article_text":"Гражданин может быть по заявлению заинтересованных лиц признан судом безвестно отсутствующим, если в течение года в месте его жительства нет сведений о месте его пребывания.\n\nПри невозможности установить день получения последних сведений об отсутствующем началом исчисления срока для признания безвестного отсутствия считается первое число месяца, следующего за тем, в котором были получены последние сведения об отсутствующем, а при невозможности установить этот месяц - первое января следующего года.","article_title":"Статья 42. Признание гражданина безвестно отсутствующим","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b06573fcb41f028f4420b44052aeb2e0b2dab43ae016ca118657dbc5525336bf"},{"code_id":"GK_RF","article_number":"420","version_date":"1994-11-30","article_text":"1. Договором признается соглашение двух или нескольких лиц об установлении, изменении или прекращении гражданских прав и обязанностей.","article_title":"Статья 420. Понятие договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9154ba2ce1e84141998e6acf8753eb919ea43eae2d2cf318672efb856e27e346"},{"code_id":"GK_RF","article_number":"421","version_date":"1994-11-30","article_text":"1. Граждане и юридические лица свободны в заключении договора.\n\nПонуждение к заключению договора не допускается, за исключением случаев, когда обязанность заключить договор предусмотрена настоящим Кодексом, законом или добровольно принятым обязательством.\n\nВ случаях, когда условие договора предусмотрено нормой, которая применяется постольку, поскольку соглашением сторон не установлено иное (диспозитивная норма), стороны могут своим соглашением исключить ее применение либо установить условие, отличное от предусмотренного в ней. При отсутствии такого соглашения условие договора определяется диспозитивной нормой.","article_title":"Статья 421. Свобода договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0a871b43e66339eba4073220e4dbf1d9a0b0cba96552558b7b6118199ced1a59"},{"code_id":"GK_RF","article_number":"422","version_date":"1994-11-30","article_text":"1. Договор должен соответствовать обязательным для сторон правилам, установленным законом и иными правовыми актами (императивным нормам), действующим в момент его заключения.\n\n2. Если после заключения договора принят закон, устанавливающий обязательные для сторон правила иные, чем те, которые действовали при заключении договора, условия заключенного договора сохраняют силу, кроме случаев, когда в законе установлено, что его действие распространяется на отношения, возникшие из ранее заключенных договоров.","article_title":"Статья 422. Договор и закон","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b353b75c9b83016593adc24237aff481545575142f6071852b79ec93540de00d"},{"code_id":"GK_RF","article_number":"423","version_date":"1994-11-30","article_text":"1. Договор, по которому сторона должна получить плату или иное встречное предоставление за исполнение своих обязанностей, является возмездным.\n\n2. Безвозмездным признается договор, по которому одна сторона обязуется предоставить что-либо другой стороне без получения от нее платы или иного встречного предоставления.\n\n3. Договор предполагается возмездным, если из закона, иных правовых актов, содержания или существа договора не вытекает иное.","article_title":"Статья 423. Возмездный и безвозмездный договоры","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0f67a7acb24c47fb42af64db2f0858979327104c7586bd75ab73b038159ad0a0"},{"code_id":"GK_RF","article_number":"424","version_date":"1994-11-30","article_text":"1. Исполнение договора оплачивается по цене, установленной соглашением сторон.\n\nВ предусмотренных законом случаях применяются цены (тарифы, расценки, ставки и т.п.), устанавливаемые или регулируемые уполномоченными на то государственными органами и (или) органами местного самоуправления. (В редакции Федерального закона от 29.06.2009 № 132-ФЗ)\n\n2. Изменение цены после заключения договора допускается в случаях и на условиях, предусмотренных договором, законом либо в установленном законом порядке.\n\n3. В случаях, когда в возмездном договоре цена не предусмотрена и не может быть определена исходя из условий договора, исполнение договора должно быть оплачено по цене, которая при сравнимых обстоятельствах обычно взимается за аналогичные товары, работы или услуги.","article_title":"Статья 424. Цена","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3ff1ffc61d46a120835f4cf1ff9580ff4d9d073e3df42a303e7f50fb05d7e0b2"},{"code_id":"GK_RF","article_number":"425","version_date":"1994-11-30","article_text":"1. Договор вступает в силу и становится обязательным для сторон с момента его заключения.\n\nДоговор, в котором отсутствует такое условие, признается действующим до определенного в нем момента окончания исполнения сторонами обязательства.","article_title":"Статья 425. Действие договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"acb77375a97847e77add997682a4c2bb3974cb77ca181604287761e2d467e084"},{"code_id":"GK_RF","article_number":"426","version_date":"1994-11-30","article_text":"1. Публичным договором признается договор, заключенный лицом, осуществляющим предпринимательскую или иную приносящую доход деятельность, и устанавливающий его обязанности по продаже товаров, выполнению работ либо оказанию услуг, которые такое лицо по характеру своей деятельности должно осуществлять в отношении каждого, кто к нему обратится (розничная торговля, перевозка транспортом общего пользования, услуги связи, энергоснабжение, медицинское, гостиничное обслуживание и т.п.).\n\nЛицо, осуществляющее предпринимательскую или иную приносящую доход деятельность, не вправе оказывать предпочтение одному лицу перед другим лицом в отношении заключения публичного договора, за исключением случаев, предусмотренных законом или иными правовыми актами.\n\n(Пункт в редакции Федерального закона от 08.03.2015 № 42-ФЗ)\n\nПри необоснованном уклонении лица, осуществляющего предпринимательскую или иную приносящую доход деятельность, от заключения публичного договора применяются положения, предусмотренные пунктом 4 статьи 445 настоящего Кодекса.  (В редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 426. Публичный договор","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"83a35aea5cba90b22b4695e8c11457b01dd857aab81e3be52c7934c79867cd2f"},{"code_id":"GK_RF","article_number":"427","version_date":"1994-11-30","article_text":"1. В договоре может быть предусмотрено, что его отдельные условия определяются примерными условиями, разработанными для договоров соответствующего вида и опубликованными в печати.","article_title":"Статья 427. Примерные условия договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e6c6b95e96803425fc94205471702ba7bc08d1f8d9849a729948ec1bd0870fc8"},{"code_id":"GK_RF","article_number":"428","version_date":"1994-11-30","article_text":"1. Договором присоединения признается договор, условия которого определены одной из сторон в формулярах или иных стандартных формах и могли быть приняты другой стороной не иначе как путем присоединения к предложенному договору в целом.\n\n2. Присоединившаяся к договору сторона вправе потребовать расторжения или изменения договора, если договор присоединения хотя и не противоречит закону и иным правовым актам, но лишает эту сторону прав, обычно предоставляемых по договорам такого вида, исключает или ограничивает ответственность другой стороны за нарушение обязательств либо содержит другие явно обременительные для присоединившейся стороны условия, которые она исходя из своих разумно понимаемых интересов не приняла бы при наличии у нее возможности участвовать в определении условий договора.\n\nЕсли иное не установлено законом или не вытекает из существа обязательства, в случае изменения или расторжения договора судом по требованию присоединившейся к договору стороны договор считается действовавшим в измененной редакции либо соответственно не действовавшим с момента его заключения. (Дополнение абзацем - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 428. Договор присоединения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"eccc50e62e1a27952c09723b5c6cdfaaf9623e5b948e256bd139b16082b3e27d"},{"code_id":"GK_RF","article_number":"429","version_date":"1994-11-30","article_text":"1. По предварительному договору стороны обязуются заключить в будущем договор о передаче имущества, выполнении работ или оказании услуг (основной договор) на условиях, предусмотренных предварительным договором.\n\n2. Предварительный договор заключается в форме, установленной для основного договора, а если форма основного договора не установлена, то в письменной форме. Несоблюдение правил о форме предварительного договора влечет его ничтожность.\n\nЕсли такой срок в предварительном договоре не определен, основной договор подлежит заключению в течение года с момента заключения предварительного договора.\n\nименяются положения, предусмотренные пунктом 4 статьи 445 настоящего Кодекса. Требование о понуждении к заключению основного договора может быть заявлено в течение шести месяцев с момента неисполнения обязательства по заключению договора.\n\nВ случае возникновения разногласий сторон относительно условий основного договора такие условия определяются в соответствии с решением суда. Основной договор в этом случае считается заключенным с момента вступления в законную силу решения суда или с момента, указанного в решении суда.\n\n(Пункт в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 429. Предварительный договор","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3c101ebfe2de8bee587152b94abe72a2d38422c00764c2e9e3d89fdd482f7a18"},{"code_id":"GK_RF","article_number":"429.1","version_date":"1994-11-30","article_text":"1. Рамочным договором (договором с открытыми условиями) признается договор, определяющий общие условия обязательственных взаимоотношений сторон, которые могут быть конкретизированы и уточнены сторонами путем заключения отдельных договоров, подачи заявок одной из сторон или иным образом на основании либо во исполнение рамочного договора.\n\n2. К отношениям сторон, не урегулированным отдельными договорами, в том числе в случае незаключения сторонами отдельных договоров, подлежат применению общие условия, содержащиеся в рамочном договоре, если иное не указано в отдельных договорах или не вытекает из существа обязательства.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 429.1. Рамочный договор","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"776526e44ff1a0c08f11198566997a81384fd33834b7e9f31880371c2d05a8c2"},{"code_id":"GK_RF","article_number":"429.2","version_date":"1994-11-30","article_text":"1. В силу соглашения о предоставлении опциона на заключение договора (опцион на заключение договора) одна сторона посредством безотзывной оферты предоставляет другой стороне право заключить один или несколько договоров на условиях, предусмотренных опционом. Опцион на заключение договора предоставляется за плату или другое встречное предоставление, если иное не предусмотрено соглашением, в том числе заключенным между коммерческими организациями. Другая сторона вправе заключить договор путем акцепта такой оферты в порядке, в сроки и на условиях, которые предусмотрены опционом.\n\nОпционом на заключение договора может быть предусмотрено, что акцепт возможен только при наступлении определенного таким опционом условия, в том числе зависящего от воли одной из сторон.\n\n2. В случае, когда опционом на заключение договора срок для акцепта безотзывной оферты не установлен, этот срок считается равным одному году, если иное не вытекает из существа договора или обычаев.\n\n3. Если опционом на заключение договора не предусмотрено иное, платеж по нему не засчитывается в счет платежей по договору, заключаемому на основании безотзывной оферты, и не подлежит возврату в случае, когда не будет акцепта.\n\n4. Опцион на заключение договора должен содержать условия, позволяющие определить предмет и другие существенные условия договора, подлежащего заключению.\n\nПредмет договора, подлежащего заключению, может быть описан любым способом, позволяющим его идентифицировать на момент акцепта безотзывной оферты.\n\n5. Опцион на заключение договора заключается в форме, установленной для договора, подлежащего заключению.\n\n6. Опцион на заключение договора может быть включен в другое соглашение, если иное не вытекает из существа такого соглашения.\n\n7. Права по опциону на заключение договора могут быть уступлены другому лицу, если иное не предусмотрено этим соглашением или не вытекает из его существа.\n\n8. Особенности отдельных видов опционов на заключение договора могут быть установлены законом.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 429.2. Опцион на заключение договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2e0a6e6260735f9f7cc1929ddca5685f3d411b66dae489fffee0aa3b2aa4d37d"},{"code_id":"GK_RF","article_number":"429.3","version_date":"1994-11-30","article_text":"1. По опционному договору одна сторона на условиях, предусмотренных этим договором, вправе потребовать в установленный договором срок от другой стороны совершения предусмотренных опционным договором действий (в том числе уплатить денежные средства, передать или принять имущество), и при этом, если управомоченная сторона не заявит требование в указанный срок, опционный договор прекращается. Опционным договором может быть предусмотрено, что требование по опционному договору считается заявленным при наступлении определенных таким договором обстоятельств.\n\n2. За право заявить требование по опционному договору сторона уплачивает предусмотренную таким договором денежную сумму, за исключением случаев, если опционным договором, в том числе заключенным между коммерческими организациями, предусмотрена его безвозмездность либо если заключение такого договора обусловлено иным обязательством или иным охраняемым законом интересом, которые вытекают из отношений сторон.\n\n3. При прекращении опционного договора платеж, предусмотренный пунктом 2 настоящей статьи, возврату не подлежит, если иное не предусмотрено опционным договором.\n\n4. Особенности отдельных видов опционных договоров могут быть установлены законом или в установленном им порядке.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 429.3. Опционный договор","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1a4a72a601c63edef9345fb52f9fcde053362f67aaa1dd7839ba567f122fff87"},{"code_id":"GK_RF","article_number":"429.4","version_date":"1994-11-30","article_text":"1. Договором с исполнением по требованию (абонентским договором) признается договор, предусматривающий внесение одной из сторон (абонентом) определенных, в том числе периодических, платежей или иного предоставления за право требовать от другой стороны (исполнителя) предоставления предусмотренного договором исполнения в затребованных количестве или объеме либо на иных условиях, определяемых абонентом.\n\n2. Абонент обязан вносить платежи или предоставлять иное исполнение по абонентскому договору независимо от того, было ли затребовано им соответствующее исполнение от исполнителя, если иное не предусмотрено законом или договором.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 429.4. Договор с исполнением по требованию (абонентский договор)","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8b4f8e6e381fcd401ef71860db0259936e991c3f2280335d03e145b685adf0b2"},{"code_id":"GK_RF","article_number":"43","version_date":"1994-11-30","article_text":"1. Имущество гражданина, признанного безвестно отсутствующим, при необходимости постоянного управления им передается на основании решения суда лицу, которое определяется органом опеки и попечительства и действует на основании договора о доверительном управлении, заключаемого с этим органом.\n\nИз этого имущества выдается содержание гражданам, которых безвестно отсутствующий обязан содержать, и погашается задолженность по другим обязательствам безвестно отсутствующего.\n\n2. Орган опеки и попечительства может и до истечения года со дня получения сведений о месте пребывания отсутствующего гражданина назначить управляющего его имуществом.\n\n3. Последствия признания лица безвестно отсутствующим, не предусмотренные настоящей статьей, определяются законом.","article_title":"Статья 43. Последствия признания гражданина безвестно отсутствующим","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3749a6549ef53fcf00a86a22c2380aafa2f75124938e2db4e999398fd42c0a34"},{"code_id":"GK_RF","article_number":"430","version_date":"1994-11-30","article_text":"1. Договором в пользу третьего лица признается договор, в котором стороны установили, что должник обязан произвести исполнение не кредитору, а указанному или не указанному в договоре третьему лицу, имеющему право требовать от должника исполнения обязательства в свою пользу.\n\n2. Если иное не предусмотрено законом, иными правовыми актами или договором, с момента выражения третьим лицом должнику намерения воспользоваться своим правом по договору стороны не могут расторгать или изменять заключенный ими договор без согласия третьего лица.\n\n3. Должник в договоре вправе выдвигать против требования третьего лица возражения, которые он мог бы выдвинуть против кредитора.\n\n4. В случае, когда третье лицо отказалось от права, предоставленного ему по договору, кредитор может воспользоваться этим правом, если это не противоречит закону, иным правовым актам и договору.","article_title":"Статья 430. Договор в пользу третьего лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"aebf114492e822fdff4ef88a9b2ac2dd3949667c71077269f0c32b57abb92c85"},{"code_id":"GK_RF","article_number":"431","version_date":"1994-11-30","article_text":"При толковании условий договора судом принимается во внимание буквальное значение содержащихся в нем слов и выражений. Буквальное значение условия договора в случае его неясности устанавливается путем сопоставления с другими условиями и смыслом договора в целом.\n\nЕсли правила, содержащиеся в части первой настоящей статьи, не позволяют определить содержание договора, должна быть выяснена действительная общая воля сторон с учетом цели договора. При этом принимаются во внимание все соответствующие обстоятельства, включая предшествующие договору переговоры и переписку, практику, установившуюся во взаимных отношениях сторон, обычаи, последующее поведение сторон. (В редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 431. Толкование договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8cca70f2c0dd6226c61f85b27c5da5b85c92b1c3fb5e9953c4765eaba729b236"},{"code_id":"GK_RF","article_number":"431.1","version_date":"1994-11-30","article_text":"1. Положения настоящего Кодекса о недействительности сделок (параграф 2 главы 9) применяются к договорам, если иное не установлено правилами об отдельных видах договоров и настоящей статьей.\n\n2. Сторона, которая приняла от контрагента исполнение по договору, связанному с осуществлением его сторонами предпринимательской деятельности, и при этом полностью или частично не исполнила свое обязательство, не вправе требовать признания договора недействительным, за исключением случаев признания договора недействительным по основаниям, предусмотренным статьями 173, 178 и 179 настоящего Кодекса, а также если предоставленное другой стороной исполнение связано с заведомо недобросовестными действиями этой стороны.\n\n3. В случае признания недействительным по требованию одной из сторон договора, который является оспоримой сделкой и исполнение которого связано с осуществлением его сторонами предпринимательской деятельности, общие последствия недействительности сделки (статья 167) применяются, если иные последствия недействительности договора не предусмотрены соглашением сторон, заключенным после признания договора недействительным и не затрагивающим интересов третьих лиц, а также не нарушающим публичных интересов.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 431.1. Недействительность договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"10922d80d9498a3597b510b2bc0c0e779688931108b777ae266f7443e1018ee4"},{"code_id":"GK_RF","article_number":"431.2","version_date":"1994-11-30","article_text":"1. Сторона, которая при заключении договора либо до или после его заключения дала другой стороне недостоверные заверения об обстоятельствах, имеющих значение для заключения договора, его исполнения или прекращения (в том числе относящихся к предмету договора, полномочиям на его заключение, соответствию договора применимому к нему праву, наличию необходимых лицензий и разрешений, своему финансовому состоянию либо относящихся к третьему лицу), обязана возместить другой стороне по ее требованию убытки, причиненные недостоверностью таких заверений, или уплатить предусмотренную договором неустойку.\n\nПризнание договора незаключенным или недействительным само по себе не препятствует наступлению последствий, предусмотренных абзацем первым настоящего пункта.\n\nПредусмотренная настоящей статьей ответственность наступает, если сторона, предоставившая недостоверные заверения, исходила из того, что другая сторона будет полагаться на них, или имела разумные основания исходить из такого предположения.\n\n2. Сторона, полагавшаяся на недостоверные заверения контрагента, имеющие для нее существенное значение, наряду с требованием о возмещении убытков или взыскании неустойки также вправе отказаться от договора, если иное не предусмотрено соглашением сторон.\n\n3. Сторона, заключившая договор под влиянием обмана или существенного заблуждения, вызванного недостоверными заверениями, данными другой стороной, вправе вместо отказа от договора (пункт 2 настоящей статьи) требовать признания договора недействительным (статьи 179 и 178).\n\n4. Последствия, предусмотренные пунктами 1 и 2 настоящей статьи, применяются к стороне, давшей недостоверные заверения при осуществлении предпринимательской деятельности, а равно и в связи с корпоративным договором либо договором об отчуждении акций или долей в уставном капитале хозяйственного общества, независимо от того, было ли ей известно о недостоверности таких заверений, если иное не предусмотрено соглашением сторон.\n\nВ случаях, предусмотренных абзацем первым настоящего пункта, предполагается, что сторона, предоставившая недостоверные заверения, знала, что другая сторона будет полагаться на такие заверения.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 431.2. Заверения об обстоятельствах","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4b4e88700c45ff2b5e5d63d1853e0801a9e25fe428020e957b160eed03e7a807"},{"code_id":"GK_RF","article_number":"432","version_date":"1994-11-30","article_text":"1. Договор считается заключенным, если между сторонами, в требуемой в подлежащих случаях форме, достигнуто соглашение по всем существенным условиям договора.\n\nСущественными являются условия о предмете договора, условия, которые названы в законе или иных правовых актах как существенные или необходимые для договоров данного вида, а также все те условия, относительно которых по заявлению одной из сторон должно быть достигнуто соглашение.\n\n2. Договор заключается посредством направления оферты (предложения заключить договор) одной из сторон и ее акцепта (принятия предложения) другой стороной.","article_title":"Статья 432. Основные положения о заключении договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c9114a673050a5301756f0a18fccad5c7c1c8a70344834d5dc81124e7b28def1"},{"code_id":"GK_RF","article_number":"433","version_date":"1994-11-30","article_text":"1. Договор признается заключенным в момент получения лицом, направившим оферту, ее акцепта.\n\n2. Если в соответствии с законом для заключения договора необходима также передача имущества, договор считается заключенным с момента передачи соответствующего имущества (статья 224).","article_title":"Статья 433. Момент заключения договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"771b4ab44bc0d0c55e0e69666e07e5684b6c1c6ece6d83615ebe1a6476874054"},{"code_id":"GK_RF","article_number":"434","version_date":"1994-11-30","article_text":"1. Договор может быть заключен в любой форме, предусмотренной для совершения сделок, если законом для договоров данного вида не установлена определенная форма.\n\nЕсли стороны договорились заключить договор в определенной форме, он считается заключенным после придания ему условленной формы, хотя бы законом для договоров данного вида такая форма не требовалась.","article_title":"Статья 434. Форма договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0cd2cc5ba9c0e806aa455e3df133a5c96404a100006ff75a10fcebd127787308"},{"code_id":"GK_RF","article_number":"434.1","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено законом или договором, граждане и юридические лица свободны в проведении переговоров о заключении договора, самостоятельно несут расходы, связанные с их проведением, и не отвечают за то, что соглашение не достигнуто.\n\n2. При вступлении в переговоры о заключении договора, в ходе их проведения и по их завершении стороны обязаны действовать добросовестно, в частности не допускать вступление в переговоры о заключении договора или их продолжение при заведомом отсутствии намерения достичь соглашения с другой стороной. Недобросовестными действиями при проведении переговоров предполагаются:\n\n1) предоставление стороне неполной или недостоверной информации, в том числе умолчание об обстоятельствах, которые в силу характера договора должны быть доведены до сведения другой стороны;\n\n2) внезапное и неоправданное прекращение переговоров о заключении договора при таких обстоятельствах, при которых другая сторона переговоров не могла разумно этого ожидать.\n\n3. Сторона, которая ведет или прерывает переговоры о заключении договора недобросовестно, обязана возместить другой стороне причиненные этим убытки.\n\nУбытками, подлежащими возмещению недобросовестной стороной, признаются расходы, понесенные другой стороной в связи с ведением переговоров о заключении договора, а также в связи с утратой возможности заключить договор с третьим лицом.\n\n4. Если в ходе переговоров о заключении договора сторона получает информацию, которая передается ей другой стороной в качестве конфиденциальной, она обязана не раскрывать эту информацию и не использовать ее ненадлежащим образом для своих целей независимо от того, будет ли заключен договор. При нарушении этой обязанности она должна возместить другой стороне убытки, причиненные в результате раскрытия конфиденциальной информации или использования ее для своих целей.\n\n5. Стороны могут заключить соглашение о порядке ведения переговоров. Такое соглашение может конкретизировать требования к добросовестному ведению переговоров, устанавливать порядок распределения расходов на ведение переговоров и иные подобные права и обязанности. Соглашение о порядке ведения переговоров может устанавливать неустойку за нарушение предусмотренных в нем положений.\n\nУсловия соглашения о порядке ведения переговоров, ограничивающие ответственность за недобросовестные действия сторон соглашения, ничтожны.\n\n6. Предусмотренные пунктами 3 и 4 настоящей статьи положения об обязанности стороны возместить убытки, причиненные другой стороне, не применяются к гражданам, признаваемым потребителями в соответствии с законодательством о защите прав потребителей.\n\n7. Правила настоящей статьи применяются независимо от того, был ли заключен сторонами договор по результатам переговоров.\n\n8. Правила настоящей статьи не исключают применения к отношениям, возникшим при установлении договорных обязательств, правил главы 59 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 434.1. Переговоры о заключении договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"589f244a1bf3503c1b32645f5d3820ce23ca9765ee0a386d8abb50cdf3014c4c"},{"code_id":"GK_RF","article_number":"435","version_date":"1994-11-30","article_text":"1. Офертой признается адресованное одному или нескольким конкретным лицам предложение, которое достаточно определенно и выражает намерение лица, сделавшего предложение, считать себя заключившим договор с адресатом, которым будет принято предложение.\n\nОферта должна содержать существенные условия договора.\n\n2. Оферта связывает направившее ее лицо с момента ее получения адресатом.\n\nЕсли извещение об отзыве оферты поступило ранее или одновременно с самой офертой, оферта считается не полученной.","article_title":"Статья 435. Оферта","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"892aab062a0092bf12c85468537283b7718e473193e3239e975462d19f29da1f"},{"code_id":"GK_RF","article_number":"436","version_date":"1994-11-30","article_text":"Полученная адресатом оферта не может быть отозвана в течение срока, установленного для ее акцепта, если иное не оговорено в самой оферте либо не вытекает из существа предложения или обстановки, в которой оно было сделано.","article_title":"Статья 436. Безотзывность оферты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b812c5e2e8b2dd82fe3152d73cd54f579a9ed29f7132a48dc936fdc1f41fb99e"},{"code_id":"GK_RF","article_number":"437","version_date":"1994-11-30","article_text":"1. Реклама и иные предложения, адресованные неопределенному кругу лиц, рассматриваются как приглашение делать оферты, если иное прямо не указано в предложении.\n\n2. Содержащее все существенные условия договора предложение, из которого усматривается воля лица, делающего предложение, заключить договор на указанных в предложении условиях с любым, кто отзовется, признается офертой (публичная оферта).","article_title":"Статья 437. Приглашение делать оферты. Публичная оферта","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bd12bfc6c8d4983179a54327584162ea19b7e447174f02b1e98e3674e6e13854"},{"code_id":"GK_RF","article_number":"438","version_date":"1994-11-30","article_text":"1. Акцептом признается ответ лица, которому адресована оферта, о ее принятии.\n\nАкцепт должен быть полным и безоговорочным.","article_title":"Статья 438. Акцепт","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f62848256f970139a396abf78d3d3bd444365897a06ea281478d8f085aa1006b"},{"code_id":"GK_RF","article_number":"439","version_date":"1994-11-30","article_text":"Если извещение об отзыве акцепта поступило лицу, направившему оферту, ранее акцепта или одновременно с ним, акцепт считается не полученным.","article_title":"Статья 439. Отзыв акцепта","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"03d0fe18021045598fc2e68f009bb98c5220c0f61ce97a1e0c19259c5de51542"},{"code_id":"GK_RF","article_number":"44","version_date":"1994-11-30","article_text":"В случае явки или обнаружения места пребывания гражданина, признанного безвестно отсутствующим, суд отменяет решение о признании его безвестно отсутствующим. На основании решения суда отменяется управление имуществом этого гражданина.","article_title":"Статья 44. Отмена решения о признании гражданина безвестно отсутствующим","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fc1112b5ca644c9798e0cbefc3025824a0e1623d0d13c8ae756eb8b64a3fbf6b"},{"code_id":"GK_RF","article_number":"440","version_date":"1994-11-30","article_text":"Когда в оферте определен срок для акцепта, договор считается заключенным, если акцепт получен лицом, направившим оферту, в пределах указанного в ней срока.","article_title":"Статья 440. Заключение договора на основании оферты, определяющей срок для акцепта","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c745efb2c4602874f44068df245835404dc87eb69f3ee1168fe981daea9b3302"},{"code_id":"GK_RF","article_number":"441","version_date":"1994-11-30","article_text":"1. Когда в письменной оферте не определен срок для акцепта, договор считается заключенным, если акцепт получен лицом, направившим оферту, до окончания срока, установленного законом или иными правовыми актами, а если такой срок не установлен, - в течение нормально необходимого для этого времени.\n\n2. Когда оферта сделана устно без указания срока для акцепта, договор считается заключенным, если другая сторона немедленно заявила о ее акцепте.","article_title":"Статья 441. Заключение договора на основании оферты, не определяющей срок для акцепта","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2f4538d51d27b89e531c7ded2b35a39e0c848e70474f962fa17a0a46f1149eea"},{"code_id":"GK_RF","article_number":"442","version_date":"1994-11-30","article_text":"В случаях, когда своевременно направленное извещение об акцепте получено с опозданием, акцепт не считается опоздавшим, если сторона, направившая оферту, немедленно не уведомит другую сторону о получении акцепта с опозданием.\n\nЕсли сторона, направившая оферту, немедленно сообщит другой стороне о принятии ее акцепта, полученного с опозданием, договор считается заключенным.","article_title":"Статья 442. Акцепт, полученный с опозданием","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9d2b2b01b7fb72bbb3cf44eeaa6792ae621149bc1bcdf0611790072bf5ec4326"},{"code_id":"GK_RF","article_number":"443","version_date":"1994-11-30","article_text":"Ответ о согласии заключить договор на иных условиях, чем предложено в оферте, не является акцептом.\n\nТакой ответ признается отказом от акцепта и в то же время новой офертой.","article_title":"Статья 443. Акцепт на иных условиях","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8f8d26440b26a66bb431e8287dda7f9a6cdc029f3ec6948674efc35bc1976069"},{"code_id":"GK_RF","article_number":"444","version_date":"1994-11-30","article_text":"Если в договоре не указано место его заключения, договор признается заключенным в месте жительства гражданина или месте нахождения юридического лица, направившего оферту.","article_title":"Статья 444. Место заключения договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"24ec7bd027c221d9da96c9aa4aef7918d1d740a1c947c148532f80e8355b3825"},{"code_id":"GK_RF","article_number":"445","version_date":"1994-11-30","article_text":"1. В случаях, когда в соответствии с настоящим Кодексом или иными законами для стороны, которой направлена оферта (проект договора), заключение договора обязательно, эта сторона должна направить другой стороне извещение об акцепте, либо об отказе от акцепта, либо об акцепте оферты на иных условиях (протокол разногласий к проекту договора) в течение тридцати дней со дня получения оферты.\n\nСторона, направившая оферту и получившая от стороны, для которой заключение договора обязательно, извещение о ее акцепте на иных условиях (протокол разногласий к проекту договора), вправе передать разногласия, возникшие при заключении договора, на рассмотрение суда в течение тридцати дней со дня получения такого извещения либо истечения срока для акцепта.\n\n2. В случаях, когда в соответствии с настоящим Кодексом или иными законами заключение договора обязательно для стороны, направившей оферту (проект договора), и ей в течение тридцати дней будет направлен протокол разногласий к проекту договора, эта сторона обязана в течение тридцати дней со дня получения протокола разногласий известить другую сторону о принятии договора в ее редакции либо об отклонении протокола разногласий.\n\nПри отклонении протокола разногласий либо неполучении извещения о результатах его рассмотрения в указанный срок сторона, направившая протокол разногласий, вправе передать разногласия, возникшие при заключении договора, на рассмотрение суда.\n\n3. Правила о сроках, предусмотренные пунктами 1 и 2 настоящей статьи, применяются, если другие сроки не установлены законом, иными правовыми актами или не согласованы сторонами.\n\nСторона, необоснованно уклоняющаяся от заключения договора, должна возместить другой стороне причиненные этим убытки.","article_title":"Статья 445. Заключение договора в обязательном порядке","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c1b054e895b006c7009acb4b42198e287393e30f1fb3ad0b952790a84f16e389"},{"code_id":"GK_RF","article_number":"447","version_date":"1994-11-30","article_text":"1. Договор, если иное не вытекает из его существа, может быть заключен путем проведения торгов. Договор заключается с лицом, выигравшим торги.\n\nВыигравшим торги на аукционе признается лицо, предложившее наиболее высокую цену, а по конкурсу - лицо, которое по заключению конкурсной комиссии, заранее назначенной организатором торгов, предложило лучшие условия.\n\nФорма торгов определяется собственником продаваемой вещи или обладателем реализуемого имущественного права, если иное не предусмотрено законом.\n\nК организованным торгам правила, предусмотренные статьями 448 и 449 настоящего Кодекса, не применяются, если иное не установлено законом.\n\n(Пункт в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 447. Заключение договора на торгах","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6a1a15c17566a4608dcd7d4741e4f54cea74c351af2d793b5e66cd6a56313cc8"},{"code_id":"GK_RF","article_number":"448","version_date":"1994-11-30","article_text":"1. Аукционы и конкурсы могут быть открытыми и закрытыми. В открытом аукционе и открытом конкурсе может участвовать любое лицо. В закрытом аукционе и закрытом конкурсе участвуют только лица, специально приглашенные для этой цели.\n\n2. Если иное не предусмотрено законом, извещение о проведении торгов должно быть опубликовано организатором не позднее чем за тридцать дней до их проведения. Извещение должно содержать сведения о времени, месте и форме торгов, об их предмете, о существующих обременениях продаваемого имущества и о порядке проведения торгов, в том числе об оформлении участия в торгах, определении лица, выигравшего торги, а также сведения о начальной цене.\n\n3. Условия договора, заключаемого по результатам торгов, определяются организатором торгов и должны быть указаны в извещении о проведении торгов.\n\n4. Если иное не предусмотрено в законе или в извещении о проведении торгов, организатор открытых торгов, опубликовавший извещение, вправе отказаться от проведения аукциона в любое время, но не позднее чем за три дня до наступления даты его проведения, а от проведения конкурса - не позднее чем за тридцать дней до проведения конкурса.\n\nВ случае, если организатор открытых торгов отказался от их проведения с нарушением указанных сроков, он обязан возместить участникам понесенный ими реальный ущерб.\n\nОрганизатор закрытого аукциона или закрытого конкурса обязан возместить приглашенным им участникам реальный ущерб независимо от того, в какой именно срок после направления извещения последовал отказ от проведения торгов.\n\n5. Участники торгов вносят задаток в размере, в сроки и в порядке, которые указаны в извещении о проведении торгов. Если торги не состоялись, задаток подлежит возврату. Задаток возвращается также лицам, которые участвовали в торгах, но не выиграли их.\n\nПри заключении договора с лицом, выигравшим торги, сумма внесенного им задатка засчитывается в счет исполнения обязательств по заключенному договору.\n\nЕсли иное не установлено законом, обязательства организатора и участников торгов по заключению договора по результатам торгов могут обеспечиваться независимой гарантией.\n\n6. Если иное не установлено законом, лицо, выигравшее торги, и организатор торгов подписывают в день проведения аукциона или конкурса протокол о результатах торгов, который имеет силу договора.\n\nЛицо, уклонившееся от подписания протокола, обязано возместить причиненные этим убытки в части, превышающей размер предоставленного обеспечения.\n\nЕсли в соответствии с законом заключение договора возможно только путем проведения торгов, при уклонении организатора торгов от подписания протокола победитель торгов вправе обратиться в суд с требованием о понуждении заключить договор, а также о возмещении убытков, вызванных уклонением от его заключения.\n\n1) по основаниям, установленным законом;\n\n2) в связи с изменением размера процентов за пользование займом при изменении ключевой ставки Банка России (соразмерно такому изменению), если на торгах заключался договор займа (кредита);\n\n3) по иным основаниям, если изменение договора не повлияет на его условия, имевшие существенное значение для определения цены на торгах.\n\n(Пункт в редакции Федерального закона от 26.07.2017 № 212-ФЗ)\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 448. Организация и порядок проведения торгов","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0c989d036ceaf595178ba2862471b056ec203217e0d08b3b9aa4cad4ef25c2c4"},{"code_id":"GK_RF","article_number":"449","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 08.03.2015 № 42-ФЗ)\n\n1. Торги, проведенные с нарушением правил, установленных законом, могут быть признаны судом недействительными по иску заинтересованного лица в течение одного года со дня проведения торгов.\n\nТорги могут быть признаны недействительными в случае, если:\n\nкто-либо необоснованно был отстранен от участия в торгах;\n\nна торгах неосновательно была не принята высшая предложенная цена;\n\nпродажа была произведена ранее указанного в извещении срока;\n\nбыли допущены иные существенные нарушения порядка проведения торгов, повлекшие неправильное определение цены продажи;\n\nбыли допущены иные нарушения правил, установленных законом.\n\n(Пункт в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 449. Основания и последствия признания торгов недействительными","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8fd798e54ede29da542f910df00db68f7e30ef231215837be6087dd9f32318d0"},{"code_id":"GK_RF","article_number":"449.1","version_date":"1994-11-30","article_text":"Извещение должно содержать наряду со сведениями, указанными в пункте 2 статьи 448 настоящего Кодекса, указание на собственника (правообладателя) имущества.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 449.1. Публичные торги","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"df8078e72b34cac28c28b62189cb106ac531df531b41bfe92f6d54a1fd3b0750"},{"code_id":"GK_RF","article_number":"45","version_date":"1994-11-30","article_text":"1. Гражданин может быть объявлен судом умершим, если в месте его жительства нет сведений о месте его пребывания в течение пяти лет, а если он пропал без вести при обстоятельствах, угрожавших смертью или дающих основание предполагать его гибель от определенного несчастного случая, - в течение шести месяцев.\n\n2. Военнослужащий или иной гражданин, пропавший без вести в связи с военными действиями, может быть объявлен судом умершим не ранее чем по истечении двух лет со дня окончания военных действий.","article_title":"Статья 45. Объявление гражданина умершим","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4279c6af9afe2f66edf6807c7ca9d3593a64d1360f149c9f7764a379adea831b"},{"code_id":"GK_RF","article_number":"450","version_date":"1994-11-30","article_text":"1. Изменение и расторжение договора возможны по соглашению сторон, если иное не предусмотрено настоящим Кодексом, другими законами или договором.\n\nМногосторонним договором, исполнение которого связано с осуществлением всеми его сторонами предпринимательской деятельности, может быть предусмотрена возможность изменения или расторжения такого договора по соглашению как всех, так и большинства лиц, участвующих в указанном договоре, если иное не установлено законом. В указанном в настоящем абзаце договоре может быть предусмотрен порядок определения такого большинства. (Дополнение абзацем - Федеральный закон от 08.03.2015 № 42-ФЗ)\n\n2. По требованию одной из сторон договор может быть изменен или расторгнут по решению суда только:\n\n1) при существенном нарушении договора другой стороной;\n\n2) в иных случаях, предусмотренных настоящим Кодексом, другими законами или договором.\n\nСущественным признается нарушение договора одной из сторон, которое влечет для другой стороны такой ущерб, что она в значительной степени лишается того, на что была вправе рассчитывать при заключении договора.","article_title":"Статья 450. Основания изменения и расторжения договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"228ac3bded2caf98ddd961cc63e0055280f2663b30a1b5f1e79c288d5c83d4c9"},{"code_id":"GK_RF","article_number":"450.1","version_date":"1994-11-30","article_text":"1. Предоставленное настоящим Кодексом, другими законами, иными правовыми актами или договором право на односторонний отказ от договора (исполнения договора) (статья 310) может быть осуществлено управомоченной стороной путем уведомления другой стороны об отказе от договора (исполнения договора). Договор прекращается с момента получения данного уведомления, если иное не предусмотрено настоящим Кодексом, другими законами, иными правовыми актами или договором.\n\n2. В случае одностороннего отказа от договора (исполнения договора) полностью или частично, если такой отказ допускается, договор считается расторгнутым или измененным.\n\n3. В случае отсутствия у одной из сторон договора лицензии на осуществление деятельности или членства в саморегулируемой организации, необходимых для исполнения обязательства по договору, другая сторона вправе отказаться от договора (исполнения договора) и потребовать возмещения убытков.\n\n4. Сторона, которой настоящим Кодексом, другими законами, иными правовыми актами или договором предоставлено право на отказ от договора (исполнения договора), должна при осуществлении этого права действовать добросовестно и разумно в пределах, предусмотренных настоящим Кодексом, другими законами, иными правовыми актами или договором.\n\n5. В случаях, если при наличии оснований для отказа от договора (исполнения договора) сторона, имеющая право на такой отказ, подтверждает действие договора, в том числе путем принятия от другой стороны предложенного последней исполнения обязательства, последующий отказ по тем же основаниям не допускается.\n\n6. Если иное не предусмотрено настоящим Кодексом, другими законами, иными правовыми актами или договором, в случаях, когда сторона, осуществляющая предпринимательскую деятельность, при наступлении обстоятельств, предусмотренных настоящим Кодексом, другими законами, иными правовыми актами или договором и служащих основанием для осуществления определенного права по договору, заявляет отказ от осуществления этого права, в последующем осуществление этого права по тем же основаниям не допускается, за исключением случаев, когда аналогичные обстоятельства наступили вновь.\n\n7. В случаях, установленных настоящим Кодексом, другими законами, иными правовыми актами или договором, правила пункта 6 настоящей статьи применяются при неосуществлении определенного права в срок, предусмотренный настоящим Кодексом, другими законами, иными правовыми актами или договором.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 450.1. Отказ от договора (исполнения договора) или от осуществления прав по договору","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"740a4dee8223b33cf83f1d1290652efe1fddf3f2388ab899b07c5cbeee4d2483"},{"code_id":"GK_RF","article_number":"451","version_date":"1994-11-30","article_text":"1. Существенное изменение обстоятельств, из которых стороны исходили при заключении договора, является основанием для его изменения или расторжения, если иное не предусмотрено договором или не вытекает из его существа.\n\nИзменение обстоятельств признается существенным, когда они изменились настолько, что, если бы стороны могли это разумно предвидеть, договор вообще не был бы ими заключен или был бы заключен на значительно отличающихся условиях.\n\n2. Если стороны не достигли соглашения о приведении договора в соответствие с существенно изменившимися обстоятельствами или о его расторжении, договор может быть расторгнут, а по основаниям, предусмотренным пунктом 4 настоящей статьи, изменен судом по требованию заинтересованной стороны при наличии одновременно следующих условий:\n\n1) в момент заключения договора стороны исходили из того, что такого изменения обстоятельств не произойдет;\n\n2) изменение обстоятельств вызвано причинами, которые заинтересованная сторона не могла преодолеть после их возникновения при той степени заботливости и осмотрительности, какая от нее требовалась по характеру договора и условиям оборота;\n\n3) исполнение договора без изменения его условий настолько нарушило\n\nбы соответствующее договору соотношение имущественных интересов сторон и повлекло бы для заинтересованной стороны такой ущерб, что она в значительной степени лишилась бы того, на что была вправе рассчитывать при заключении договора;4) из обычаев или существа договора не вытекает, что риск изменения обстоятельств несет заинтересованная сторона. (В редакции Федерального закона от 08.03.2015 № 42-ФЗ)3. При расторжении договора вследствие существенно изменившихся обстоятельств суд по требованию любой из сторон определяет последствия расторжения договора, исходя из необходимости справедливого распределения между сторонами расходов, понесенных ими в связи с исполнением этого договора.4. Изменение договора в связи с существенным изменением обстоятельств допускается по решению суда в исключительных случаях, когда расторжение договора противоречит общественным интересам либо повлечет для сторон ущерб, значительно превышающий затраты, необходимые для исполнения договора на измененных судом условиях.Статья 452. Порядок изменения и расторжения договора1. Соглашение об изменении или о расторжении договора совершается в той же форме, что и договор, если из закона, иных правовых актов, договора или обычаев не вытекает иное. (В редакции Федерального закона от 08.03.2015 № 42-ФЗ)2. Требование об изменении или о расторжении договора может быть заявлено стороной в суд только после получения отказа другой стороны на предложение изменить или расторгнуть договор либо неполучения ответа в срок, указанный в предложении или установленный законом либо договором, а при его отсутствии - в тридцатидневный срок.Статья 453. Последствия изменения и расторжения договора1. При изменении договора обязательства сторон сохраняются в измененном виде.2. При расторжении договора обязательства сторон прекращаются, если иное не предусмотрено законом, договором или не вытекает из существа обязательства. (В редакции Федерального закона от 08.03.2015 № 42-ФЗ)3. В случае изменения или расторжения договора обязательства считаются измененными или прекращенными с момента заключения соглашения сторон об изменении или о расторжении договора, если иное не вытекает из соглашения.В случае изменения или расторжения договора в судебном порядке обязательства считаются измененными или прекращенными с момента вступления в законную силу решения суда об изменении или о расторжении договора, если этим решением не предусмотрена дата, с которой обязательства считаются соответственно измененными или прекращенными. Такая дата определяется судом исходя из существа договора и (или) характера правовых последствий его изменения, но не может быть ранее даты наступления обстоятельств, послуживших основанием для изменения или расторжения договора.(Пункт в редакции  Федерального закона от 24.07.2023 № 347-ФЗ)4. Стороны не вправе требовать возвращения того, что было исполнено ими по обязательству до момента изменения или расторжения договора, если иное не установлено законом или соглашением сторон.В случае, когда до расторжения или изменения договора одна из сторон, получив от другой стороны исполнение обязательства по договору, не исполнила свое обязательство либо предоставила другой стороне неравноценное исполнение, к отношениям сторон применяются правила об обязательствах вследствие неосновательного обогащения (глава 60), если иное не предусмотрено законом или договором либо не вытекает из существа обязательства. (Дополнение абзацем - Федеральный закон от 08.03.2015 № 42-ФЗ)5. Если основанием для изменения или расторжения договора послужило существенное нарушение договора одной из сторон, другая сторона вправе требовать возмещения убытков, причиненных изменением или расторжением договора.Президент Российской Федерации                               Б.ЕльцинМосква, Кремль30 ноября 1994 года№ 51-ФЗ\n\nбы соответствующее договору соотношение имущественных интересов сторон и повлекло бы для заинтересованной стороны такой ущерб, что она в значительной степени лишилась бы того, на что была вправе рассчитывать при заключении договора;\n\n4) из обычаев или существа договора не вытекает, что риск изменения обстоятельств несет заинтересованная сторона. (В редакции Федерального закона от 08.03.2015 № 42-ФЗ)\n\n3. При расторжении договора вследствие существенно изменившихся обстоятельств суд по требованию любой из сторон определяет последствия расторжения договора, исходя из необходимости справедливого распределения между сторонами расходов, понесенных ими в связи с исполнением этого договора.\n\n4. Изменение договора в связи с существенным изменением обстоятельств допускается по решению суда в исключительных случаях, когда расторжение договора противоречит общественным интересам либо повлечет для сторон ущерб, значительно превышающий затраты, необходимые для исполнения договора на измененных судом условиях.","article_title":"Статья 451. Изменение и расторжение договора в связи с существенным изменением обстоятельств","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a86a50c392c56db3cb7b29ec71c7e482817c61f41b9219b4e08e6fc72628ed2a"},{"code_id":"GK_RF","article_number":"453","version_date":"1994-11-30","article_text":"1. При изменении договора обязательства сторон сохраняются в измененном виде.\n\nВ случае изменения или расторжения договора в судебном порядке обязательства считаются измененными или прекращенными с момента вступления в законную силу решения суда об изменении или о расторжении договора, если этим решением не предусмотрена дата, с которой обязательства считаются соответственно измененными или прекращенными. Такая дата определяется судом исходя из существа договора и (или) характера правовых последствий его изменения, но не может быть ранее даты наступления обстоятельств, послуживших основанием для изменения или расторжения договора.\n\n(Пункт в редакции  Федерального закона от 24.07.2023 № 347-ФЗ)\n\nВ случае, когда до расторжения или изменения договора одна из сторон, получив от другой стороны исполнение обязательства по договору, не исполнила свое обязательство либо предоставила другой стороне неравноценное исполнение, к отношениям сторон применяются правила об обязательствах вследствие неосновательного обогащения (глава 60), если иное не предусмотрено законом или договором либо не вытекает из существа обязательства. (Дополнение абзацем - Федеральный закон от 08.03.2015 № 42-ФЗ)\n\nПрезидент Российской Федерации                               Б.Ельцин\n\nМосква, Кремль\n\n30 ноября 1994 года","article_title":"Статья 453. Последствия изменения и расторжения договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"929a50b263ce7f19469993b5c587bc1045b28f420357ecd6b15b6d02cd94fe6d"},{"code_id":"GK_RF","article_number":"46","version_date":"1994-11-30","article_text":"1. В случае явки или обнаружения места пребывания гражданина, объявленного умершим, суд отменяет решение об объявлении его умершим.\n\n2. Независимо от времени своей явки гражданин может потребовать от любого лица возврата сохранившегося имущества, которое безвозмездно перешло к этому лицу после объявления гражданина умершим, за исключением случаев, предусмотренных пунктом 3 статьи 302 настоящего Кодекса.\n\nЛица, к которым имущество гражданина, объявленного умершим, перешло по возмездным сделкам, обязаны возвратить ему это имущество, если доказано, что, приобретая имущество, они знали, что гражданин, объявленный умершим, находится в живых. При невозможности возврата такого имущества в натуре возмещается его стоимость.","article_title":"Статья 46. Последствия явки гражданина, объявленного умершим","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"79f6a83d14ee2d585ce985ede04307fb613bf1ae8dad01d5570c8c453ead42f3"},{"code_id":"GK_RF","article_number":"47","version_date":"1994-11-30","article_text":"1. Государственной регистрации подлежат следующие акты гражданского состояния:\n\n1) рождение;\n\n2) заключение брака;\n\n3) расторжение брака;\n\n4) усыновление (удочерение);\n\n5) установление отцовства;\n\n6) перемена имени;\n\n7) смерть гражданина.\n\nПри наличии спора между заинтересованными лицами либо отказе органов, осуществляющих государственную регистрацию актов гражданского состояния, в исправлении или изменении записи спор разрешается судом. (В редакции  Федерального закона от 27.01.2023 № 3-ФЗ)\n\nАннулирование и восстановление записей актов гражданского состояния производятся органами, осуществляющими государственную регистрацию актов гражданского состояния, на основании решения суда. (В редакции  Федерального закона от 27.01.2023 № 3-ФЗ)","article_title":"Статья 47. Регистрация актов гражданского состояния","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d01062ff164ed2081765d45fa8d89cfd5cc632994565e28174a4457ab42d56a9"},{"code_id":"GK_RF","article_number":"48","version_date":"1994-11-30","article_text":"1. Юридическим лицом признается организация, которая имеет обособленное имущество и отвечает им по своим обязательствам, может от своего имени приобретать и осуществлять гражданские права и нести гражданские обязанности, быть истцом и ответчиком в суде.\n\n2. Юридическое лицо должно быть зарегистрировано в едином государственном реестре юридических лиц в одной из организационно-правовых форм, предусмотренных настоящим Кодексом.\n\n3. К юридическим лицам, на имущество которых их учредители имеют вещные права, относятся государственные и муниципальные унитарные предприятия, а также учреждения.\n\nК юридическим лицам, в отношении которых их участники имеют корпоративные права, относятся корпоративные организации (статья 651).\n\n4. Правовое положение Центрального банка Российской Федерации (Банка России) определяется Конституцией Российской Федерации и законом о Центральном банке Российской Федерации.\n\n(Статья в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 48. Понятие юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"69a1257288f745dd0b0dd0c07c1d52cfa739722d5e3e59fc6b0e307a043792be"},{"code_id":"GK_RF","article_number":"49","version_date":"1994-11-30","article_text":"Коммерческие организации, за исключением унитарных предприятий и иных видов организаций, предусмотренных законом, могут иметь гражданские права и нести гражданские обязанности, необходимые для осуществления любых видов деятельности, не запрещенных законом.\n\nВ случаях, предусмотренных законом, юридическое лицо может заниматься отдельными видами деятельности только на основании специального разрешения (лицензии), членства в саморегулируемой организации или выданного саморегулируемой организацией свидетельства о допуске к определенному виду работ.  (В редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\nПраво юридического лица осуществлять деятельность, для занятия которой необходимо получение специального разрешения (лицензии), членство в саморегулируемой организации или получение свидетельства саморегулируемой организации о допуске к определенному виду работ, возникает с момента получения такого разрешения (лицензии) или в указанный в нем срок либо с момента вступления юридического лица в саморегулируемую организацию или выдачи саморегулируемой организацией свидетельства о допуске к определенному виду работ и прекращается при прекращении действия разрешения (лицензии), членства в саморегулируемой организации или выданного саморегулируемой организацией свидетельства о допуске к определенному виду работ.\n\n(Пункт в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 49. Правоспособность юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a392d152031eab7ab9a5a17e61590143189fc7042080c80d9166f448d6be60cb"},{"code_id":"GK_RF","article_number":"5","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 30.12.2012 № 302-ФЗ)","article_title":"Статья 5. Обычаи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b39a6ec70ed38789456fd9c819ea98f0d73a459b54a9e5f1ee0ba2995bc18fef"},{"code_id":"GK_RF","article_number":"50","version_date":"1994-11-30","article_text":"1. Юридическими лицами могут быть организации, преследующие извлечение прибыли в качестве основной цели своей деятельности (коммерческие организации) либо не имеющие извлечение прибыли в качестве такой цели и не распределяющие полученную прибыль между участниками (некоммерческие организации).\n\n1) потребительских кооперативов, к которым относятся в том числе жилищные, жилищно-строительные и гаражные кооперативы, общества взаимного страхования, кредитные кооперативы, фонды проката, сельскохозяйственные потребительские кооперативы; (В редакции Федерального закона от 29.07.2017 № 217-ФЗ)\n\n2) общественных организаций, к которым относятся в том числе политические партии и созданные в качестве юридических лиц профессиональные союзы (профсоюзные организации), органы общественной самодеятельности, территориальные общественные самоуправления; (В редакции Федерального закона от 23.05.2015 № 133-ФЗ)\n\n21) общественных движений; (Дополнение подпунктом - Федеральный закон от 23.05.2015 № 133-ФЗ)\n\n3) ассоциаций (союзов), к которым относятся в том числе некоммерческие партнерства, саморегулируемые организации, объединения работодателей, объединения профессиональных союзов, кооперативов и общественных организаций, торгово-промышленные палаты; (В редакции федеральных законов от 13.07.2015 № 268-ФЗ; от 07.02.2017 № 12-ФЗ)\n\n4) товариществ собственников недвижимости, к которым относятся в том числе товарищества собственников жилья, садоводческие или огороднические некоммерческие товарищества; (В редакции Федерального закона от 29.07.2017 № 217-ФЗ)\n\n5) казачьих обществ, внесенных в государственный реестр казачьих обществ в Российской Федерации;\n\n6) общин коренных малочисленных народов Российской Федерации;\n\n7) общественно полезных фондов, к которым относятся в том числе общественные и благотворительные фонды, и личных фондов; (В редакции Федерального закона от 01.07.2021 № 287-ФЗ)\n\n8) учреждений, к которым относятся государственные учреждения (в том числе государственные академии наук), муниципальные учреждения и частные (в том числе общественные) учреждения;\n\n9) автономных некоммерческих организаций;\n\n10) религиозных организаций;\n\n11) публично-правовых компаний;\n\n12) адвокатских палат; (Дополнение подпунктом - Федеральный закон от 13.07.2015 № 268-ФЗ)\n\n13) адвокатских образований (являющихся юридическими лицами); (Дополнение подпунктом - Федеральный закон от 13.07.2015 № 268-ФЗ)\n\n14) государственных корпораций; (Дополнение подпунктом - Федеральный закон от 03.07.2016 № 236-ФЗ)\n\n15) нотариальных палат. (Дополнение подпунктом - Федеральный закон от 07.02.2017 № 12-ФЗ)\n\n(Пункт в редакции Федерального закона от 05.05.2014 № 99-ФЗ)","article_title":"Статья 50. Коммерческие и некоммерческие организации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"80c4be2920f4ce389e7c52644123c6437389490a7d16480932196e7c4096b0bf"},{"code_id":"GK_RF","article_number":"50.1","version_date":"1994-11-30","article_text":"1. Юридическое лицо может быть создано на основании решения учредителя (учредителей) об учреждении юридического лица.\n\n2. В случае учреждения юридического лица одним лицом решение о его учреждении принимается учредителем единолично.\n\nВ случае учреждения юридического лица двумя и более учредителями указанное решение принимается всеми учредителями единогласно.\n\nВ решении об учреждении корпоративного юридического лица (статья 651) указываются также сведения о результатах голосования учредителей по вопросам учреждения юридического лица, о порядке совместной деятельности учредителей по созданию юридического лица.\n\nВ решении об учреждении юридического лица указываются также иные сведения, предусмотренные законом.\n\nПосле смерти гражданина нотариус, ведущий наследственное дело, направляет в уполномоченный государственный орган заявление о государственной регистрации наследственного фонда с указанием имени или наименования лица (лиц), осуществляющего полномочия единоличного исполнительного органа фонда.\n\n(Дополнение пунктом - Федеральный закон от 29.07.2017 № 259-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 05.05.2014 № 99-ФЗ)","article_title":"Статья 50.1. Решение об учреждении юридического лица","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cd0c45a77e065451fe988a4a82b1a8f5ad53866d183597424903f68e7673aa3f"},{"code_id":"GK_RF","article_number":"51","version_date":"1994-11-30","article_text":"1. Юридическое лицо подлежит государственной регистрации в уполномоченном государственном органе в порядке, предусмотренном законом о государственной регистрации юридических лиц.\n\n2. Данные государственной регистрации включаются в единый государственный реестр юридических лиц, открытый для всеобщего ознакомления.\n\nЛицо, добросовестно полагающееся на данные единого государственного реестра юридических лиц, вправе исходить из того, что они соответствуют действительным обстоятельствам. Юридическое лицо не вправе в отношениях с лицом, полагавшимся на данные единого государственного реестра юридических лиц, ссылаться на данные, не включенные в указанный реестр, а также на недостоверность данных, содержащихся в нем, за исключением случаев, если соответствующие данные включены в указанный реестр в результате неправомерных действий третьих лиц или иным путем помимо воли юридического лица. (В редакции Федерального закона от 05.05.2014 № 99-ФЗ)\n\nЮридическое лицо обязано возместить убытки, причиненные другим участникам гражданского оборота вследствие непредставления, несвоевременного представления или представления недостоверных данных о нем в единый государственный реестр юридических лиц.\n\n3. До государственной регистрации юридического лица, изменений его устава или до включения иных данных, не связанных с изменениями устава, в единый государственный реестр юридических лиц уполномоченный государственный орган обязан провести в порядке и в срок, к\n\nоторые предусмотрены законом, проверку достоверности данных, включаемых в указанный реестр.\n\n4. В случаях и в порядке, которые предусмотрены законом о государственной регистрации юридических лиц, уполномоченный государственный орган обязан заблаговременно сообщить заинтересованным лицам о предстоящей государственной регистрации изменений устава юридического лица и о предстоящем включении данных в единый государственный реестр юридических лиц.\n\nЗаинтересованные лица вправе направить в уполномоченный государственный орган возражения относительно предстоящей государственной регистрации изменений устава юридического лица или предстоящего включения данных в единый государственный реестр юридических лиц в порядке, предусмотренном законом о государственной регистрации юридических лиц. Уполномоченный государственный орган обязан рассмотреть эти возражения и принять соответствующее решение в порядке и в срок, которые предусмотрены законом о государственной регистрации юридических лиц.\n\n5. Отказ в государственной регистрации юридического лица, а также во включении данных о нем в единый государственный реестр юридических лиц допускается только в случаях, предусмотренных законом о государственной регистрации юридических лиц.\n\nОтказ в государственной регистрации юридического лица и уклонение от такой регистрации могут быть оспорены в суде.\n\n6. Государственная регистрация юридического лица может быть признана судом недействительной в связи с допущенными при его создании грубыми нарушениями закона, если эти нарушения носят неустранимый характер.\n\nВключение в единый государственный реестр юридических лиц данных о юридическом лице может быть оспорено в суде, если такие данные недостоверны или включены в указанный реестр с нарушением закона.\n\n7. Убытки, причиненные незаконным отказом в государственной регистрации юридического лица, уклонением от государственной регистрации, включением в единый государственный реестр юридических лиц недостоверных данных о юридическом лице либо нарушением порядка государственной регистрации, предусмотренного законом о государственной регистрации юридических лиц, по вине уполномоченного государственного органа, подлежат возмещению за счет казны Российской Федерации.\n\n8. Юридическое лицо считается созданным, а данные о юридическом лице считаются включенными в единый государственный реестр юридических лиц со дня внесения соответствующей записи в этот реестр.\n\n(Статья в редакции Федерального закона от 28.06.2013 № 134-ФЗ)","article_title":"Статья 51. Государственная регистрация юридических лиц","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f5f2491d6151385452a5fb96d5d1f84160c3c55267d75eeb24b55519fc530f50"}]$law7v010$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text)) insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at) select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
    commit;
